// Üretilen dosya: tool/ozgun/uret.py. Yabancı Dil · Türkçe yazım ve noktalama kuralları (orta).
const ozLanguage14Orta = <(String, String, List<String>, String)>[
  ('Sert ünsüzle biten sözcüklere gelen bulunma eki ile bağlaç olan \'de/da\' arasındaki yazım farkı nedir?', 'Bulunma eki \'ta/te\' olabilir ve bitişik yazılır; bağlaç hep \'da/de\' biçimindedir ve ayrı yazılır.', ['İkisi de sert ünsüzden sonra \'ta/te\' olur ve bitişik yazılır.', 'Bağlaç \'ta/te\' olabilir; bulunma eki hep \'da/de\' kalır.', 'İkisi de ayrı yazılır; yalnız ünlü uyumuna göre de/da biçimini alır, ünsüze bakılmaz.'], 'Bağlaç olan \'de/da\' ayrı yazılır ve sert ünsüz benzeşmesine uğramaz. Bulunma eki ise bitişiktir ve \'kitapta, ağaçta\' gibi \'ta/te\' biçimine girebilir.'),
  ('\'Kitap da defter de çantadaydı.\' cümlesinde bağlaç olan \'de\'lerin yazımıyla ilgili hangisi doğrudur?', '\'Kitap\' sert ünsüzle bitse de bağlaç \'da\' olarak ayrı yazılmıştır.', ['\'Kitap\' sert ünsüzle bittiği için \'ta\' yazılmalıydı.', 'İki bağlaç da sözcüklerle bitişik yazılmalıydı.', 'Birinci \'da\' bitişik, ikinci \'de\' ayrı yazılmalıdır, çünkü ikincisi ünlüyle başlar.'], 'Bağlaç \'de/da\' ünsüz benzeşmesine girmez. Bu yüzden \'kitap da\' ayrı ve \'da\' biçiminde yazılır.'),
  ('\'Kış geldi, kuşlar da güneye göç etti.\' cümlesinde \'da\' sözcüğünü cümleden çıkarınca temel anlam korunur. Bu durum \'da\'nın hangi işlevde olduğunu gösterir?', 'Bağlaç olduğunu', ['Bulunma eki olduğunu', 'Çıkma eki olduğunu', 'Pekiştirme sıfatı olduğunu'], 'Cümlenin temel anlamı bozulmadan çıkarılabilen \'de/da\' bağlaçtır. Ek olsaydı sözcüğün çekimi eksilir, anlam değişirdi.'),
  ('Aşağıdaki cümlelerin hangisinde \'de\' ile ilgili yazım yanlışı yoktur?', 'Bu konuda sen de haklısın ama ben de haklıyım.', ['Bu konuda sende haklısın ama bende haklıyım.', 'Bu konu da senden başka kimse bilmez.', 'Bu konuda sen de haklısında ben de haklıyım, değil mi?'], 'Birinci seçenekte iki bağlaç ayrı yazılmış; diğerlerinde ya bağlaç bitişik yazılmış ya bulunma eki ayrılmış.'),
  ('Aşağıdaki cümlelerin hangisinde çıkma eki \'-dan\' ayrı yazılarak hata yapılmıştır?', 'Öğretmen sınıf tan çıkınca öğrenciler konuşmaya başladı.', ['Öğretmen sınıftan çıkınca öğrenciler konuşmaya başladı.', 'Öğretmen sınıfta kaldı.', 'Öğretmen de sınıftan çıktı ve gitti.'], 'Hâl ekleri (\'-da, -dan, -a, -ı\') kelimeye bitişik yazılır. \'Sınıf tan\' ayrı yazılamaz; doğrusu \'sınıftan\'dır.'),
  ('Aşağıdaki sözcüklerden hangisi \'ki\' ile kurulmuş olmasına karşın bitişik yazılır?', 'çünkü', ['öyle ki', 'madem ki', 'sanki ki'], 'Bitişik yazılanlar \'çünkü, belki, sanki, oysaki, hâlbuki\' gibi kalıplaşmış sözcüklerdir. \'Öyle ki\' ve \'madem ki\' ise ayrı yazılır.'),
  ('\'Bu kalem benim, şu kalem ise seninki.\' cümlesindeki \'seninki\' sözcüğündeki \'ki\' ne işlev görür?', 'İyelik ekinden sonra gelen ilgi zamiri yapan ektir.', ['Cümleleri birbirine bağlayan bağlaçtır.', 'Kalıplaşmış bir sözcüğün parçasıdır.', 'Soru anlamı katan, ayrı yazılan bir ektir.'], '\'Benimki, seninki\' gibi sözcüklerde \'ki\' eki iyelik veya ilgi hâlinden sonra gelip zamir yapar. Bu ek bitişik yazılır.'),
  ('\'Sana söyleyeyim ki bu iş sandığın kadar kolay değil.\' cümlesinde \'ki\'nin yazımı için hangisi doğrudur?', 'Bağlaçtır, ayrı yazılmıştır; yargıyı açıklayan ikinci cümleyi bağlar.', ['İlgi ekidir, bitişik yazılmalıdır.', 'Kalıplaşmış sözcüğün parçasıdır.', 'Soru ekidir, kendinden önceki sözcüğe bitişik yazılmalıdır.'], 'Bağlaç olan \'ki\' cümleyi önceki cümleye bağlar. \'Söyleyeyim ki, bilesin ki\' gibi yerlerde ayrı yazılır.'),
  ('Aşağıdaki sözcüklerden hangisinde \'ki\' aitlik eki olarak kullanılmamıştır?', 'hâlbuki', ['masadaki', 'benimki', 'sokaktaki'], '\'Hâlbuki\' kalıplaşmış bir bağlaçtır; \'ki\' burada eklenmiş bir ek değildir. Diğerlerinde \'ki\' ilgi/aitlik ekidir.'),
  ('\'Dün gece hasta mıydın?\' sorusunda ek fiil ile soru eki arasındaki ilişki nasıl yazıya geçmiştir?', 'Soru eki ayrı, ona bitişen ek fiil \'-ydı\' soru ekine bitişik yazılmıştır.', ['Soru eki sözcüğe bitişik, ek fiil ayrı yazılmıştır.', 'Bütün öğeler tek bir sözcük gibi bitişik yazılmıştır, ayrım yoktur.', 'Ek fiil sözcüğe bitişik, soru eki sonda ayrı yazılmıştır.'], '\'Hasta mıydın\' yazımında soru eki \'mı\' ayrı durur; sonrasına gelen ek fiil ve kişi eki (\'-ydın\') soru ekine bitişir.'),
  ('\'Okula yürüyerek mi gideceksin, yoksa servisle mi?\' cümlesinde soru ekinin yazımı ve işlevi için hangisi doğrudur?', 'İki \'mi\' de ayrı yazılmış; seçenekli soru kurmaya yarar.', ['İlk \'mi\' bitişik, ikinci \'mi\' ayrı yazılmalıdır.', 'İki \'mi\' de sözcüklere bitişik yazılmalıdır.', 'Bu cümle soru cümlesi olmadığı için \'mi\' hiçbir şekilde yazılamaz.'], 'Soru eki iki seçenek arasında tercih sorusu yaparken de ayrı yazılır.'),
  ('\'Çocuk ağlıyor mu diye odaya baktı.\' cümlesinin sonuna hangi noktalama işareti konmalıdır?', 'Nokta', ['Soru işareti', 'Ünlem', 'İki nokta'], 'Soru eki içerse de cümle bir soruyu aktaran bildirme cümlesidir; dolaylı sorularda nokta kullanılır.'),
  ('\'Yemek yedin mi?\' sorusunun sonunda \'mi\' yerine \'mı\' yazmak neden yanlıştır?', 'Son ünlü \'i\' olduğu için ince ünlülü \'mi\' gelir; ünlü uyumu bozulur.', ['Soru ekinin ünlüsü hep \'ı\'dır.', '\'Yemek\' sözcüğünün sert ünsüzü \'mı\' ister.', '\'mi\' yalnız çoğul ve çekimli sözcüklerde kullanılabilir.'], '\'Yedin\' sözcüğünün son ünlüsü \'i\' (ince, düz) olduğundan soru eki \'mi\' olur.'),
  ('Kapıyı kapatanın anne olup olmadığı soruluyor. Doğru yazılmış soru hangisidir?', 'Kapıyı annem mi kapadı?', ['Kapıyı annemmi kapadı?', 'Kapıyı annem mı kapadı?', 'Kapıyı annem - mi kapadı?'], '\'Annem\' sözcüğünün son ünlüsü \'e\' olduğundan soru eki \'mi\' gelir ve ayrı yazılır.'),
  ('\'Ben sınıfta çalışıyordum, kardeşim ise bahçede oynuyordu.\' cümlesindeki \'ise\' için hangisi doğrudur?', 'Zıtlık bildiren bağlaçtır; ayrı yazılır.', ['Ek fiildir; bitişik yazılmalıdır.', 'Şart eki olduğu için \'oynuyorduysa\' biçiminde birleşmelidir.', 'Soru ekidir; \'ise\' yerine \'mi\' kullanılır.'], 'Cümlede \'ise\' iki durumu karşılaştıran ayrı bir sözcüktür. Şart bildiren ek fiil \'ise\' ise \'-sa\' olarak bitişir.'),
  ('\'Biz dün akşam evde ___.\' boşluğa ek fiilin geçmiş zaman biçimi getirilince doğru yazım hangisidir?', 'evdeydik', ['evdedik', 'evde ydik', 'evdeyidik'], 'Ünlüyle biten sözcüğe ek fiil gelirken araya kaynaştırma \'y\' girer ve ek bitişik yazılır: \'evdeydik\'.'),
  ('\'Hasta\' sözcüğüne öğrenilen geçmiş haber bildiren \'-imiş\' ek fiili getirilirse doğru yazım hangisidir?', 'hastaymış', ['hasta ymış', 'hastamış', 'hastaiymiş'], 'Ünlüyle biten sözcüğe \'imiş\' ek fiili \'y\' ile kaynaşır ve bitişik yazılır: \'hastaymış\'.'),
  ('\'Kitap ___\' sözcüğüne bildirme eki \'-dir\' getirilirse sert ünsüz benzeşmesine göre doğru yazım hangisi olur?', 'kitaptır', ['kitapdır', 'kitap tır', 'kitaptir'], '\'p\' sert ünsüzüyle biten sözcüğe \'dır\' eki \'tır\' olur; ünlü uyumuna göre \'ı\' kalır. Ek bitişik yazılır.'),
  ('\'Pazar ertesi\' sözcüklerinin birleşmesiyle oluşan gün adı hangisidir ve nasıl yazılır?', 'Pazartesi; bitişik', ['Pazar ertesi; ayrı', 'Pazar-ertesi; kısa çizgiyle', 'Pazarertesi; sıfır ses olayıyla'], 'Birleşirken \'e\' ünlüsü \'t\' ile türemiş: \'pazartesi\'. Bitişik yazılır.'),
  ('Aşağıdaki sözcüklerden hangisinin yazımı TDK Yazım Kılavuzu\'na göre yanlıştır?', 'hanım eli', ['başöğretmen', 'kuşburnu', 'gökkuşağı'], '\'Hanımeli\' bitkisi bitişik yazılır. \'Hanım eli\' ayrı yazımı yanlıştır.'),
  ('Aşağıdaki sözcük çiftlerinden hangisinde ikisi de bitişik yazılan birleşik sözcüktür?', 'yıldönümü, kuşburnu', ['gün batımı, ay çiçeği', 'yıl dönümü, kuş burnu', 'okul öncesi, gök yüzü'], '\'Yıldönümü\' ve \'kuşburnu\' TDK\'ye göre bitişik yazılır. Diğer seçeneklerde ayrı yazılan sözcükler vardır.'),
  ('\'Sınıf içinde çoluk çocuk herkes toplanmıştı.\' cümlesinde \'çoluk çocuk\' ikilemesi için hangisi doğrudur?', 'Birbirine yakın anlamlı iki sözcükten kurulmuştur ve ayrı yazılır.', ['Pekiştirme heceli bir sıfattır ve bitişik yazılır.', 'Kalıplaşmış birleşik sözcüktür ve bitişik yazılır.', 'Yansıma sözcüktür ve iki sözcüğün aralarına kısa çizgi gelir.'], 'İkilemeler ayrı yazılır. \'Çoluk çocuk\' gibi anlamca ilişkili iki sözcüğün birlikte kullanılmasıdır.'),
  ('\'Yan yana oturan iki arkadaş, el ele verip çalıştı.\' cümlesinde \'yan yana\' ve \'el ele\' için hangisi doğrudur?', 'İkisi de tekrarlı öbektir ve ayrı yazılır.', ['\'Yanyana\' bitişik, \'el ele\' ayrı yazılmalıdır.', '\'Yanyana\' ve \'elele\' bitişik yazılmalıdır.', 'Yalnız \'el ele\' ayrı, \'yan yana\' kısa çizgiyle yazılır.'], '\'Yan yana, el ele, arka arkaya\' gibi tekrar yoluyla oluşan öbekler ayrı yazılır.'),
  ('Aşağıdakilerden hangisi yansıma sözcüğün tekrarıyla kurulmuş bir ikilemedir ve ayrı yazılır?', 'tıkır tıkır', ['masmavi', 'gökyüzü', 'karabiber'], '\'Tıkır tıkır\' yansıma sözcüğün tekrarıyla oluşan ikilemedir. Diğerleri pekiştirme ya da birleşik sözcüktür ve bitişik yazılır.'),
  ('\'Her öğrenciye ___ kalem verildi.\' boşluğa \'iki\' sayısının dağıtma biçimi gelirse doğru yazım hangisi olur?', 'ikişer', ['iki şer', 'ikişer yerine ikişer\'er', 'ikiser'], 'Dağıtma sayı sıfatı \'-er/-şer\' ekiyle kurulur: ünlüyle biten sayılarda \'-şer\' gelir. \'İkişer\' bitişiktir.'),
  ('\'Bin dokuz yüz seksen dört\' sayısı sözcükle yazılırken aşağıdakilerden hangisi doğrudur?', 'Her sayı sözcüğü ayrı yazılır.', ['Yüzlükler birleşik yazılır.', 'Tamamı bitişik yazılır.', 'Binler ve yüzler kısa çizgiyle bağlanır.'], 'TDK\'ye göre sayılar sözcükle yazılırken ayrı yazılır; yalnız belge ve çek gibi karışıklığı önlemek gereken yerlerde bitişik yazılabilir.'),
  ('\'Üçte bir\', \'yüzde beş\' ve \'binde iki\' ifadelerinin yazımı için hangisi doğrudur?', 'Ayrı yazılırlar; \'-te/-de\' eki sayıya bitişiktir.', ['Üçü de tek sözcük olarak bitişik yazılır.', 'Yalnız \'üçte bir\' kısa çizgiyle yazılır; diğerleri ayrıdır.', '\'-de\' eki ayrı yazılır: \'yüz de beş\'.'], 'Kesir ve oran bildiren bu ifadelerde ek sayıya bitişir, ardından gelen sayı ayrı yazılır.'),
  ('Aşağıdaki sözcüklerden hangisi \'onlarca, yüzlerce, binlerce\' ile aynı yapıda kurulmuştur?', 'milyonlarca', ['on beş', 'iki buçuk', 'üçer'], 'Bunlar sayıya çokluk ve \'-ca\' ekinin getirilmesiyle kurulmuş, bitişik yazılan sözcüklerdir.'),
  ('\'Beşinci\' sözcüğü ile rakamlı yazım olan \'5.\' için hangisi doğrudur?', 'Rakamla yazılırken \'5.\' biçiminde sayının yanına nokta konur.', ['Rakamla yazılırken \'5\'inci\' biçimi tek doğrusudur.', '\'5.\' yazılırken nokta konmaz.', '\'5nci\' biçiminde yazılır.'], 'Sıra sayısı rakamla yazılırken rakamın yanına nokta konur (\'5. sınıf\'). Ek getirilirse kesmeyle ayrılabilir (\'5\'inci\').'),
  ('Aşağıdaki cümlelerin hangisinde büyük harf kullanımı yanlıştır?', 'Bahar geldiğinde Nisan ayında Kırlangıçlar dönerler.', ['Doğu Anadolu Bölgesi\'nde kış uzun sürer.', 'Ali Bey toplantıya katıldı.', 'Türkçe öğretmenimiz yeni kitap önerdi.'], 'Kuş adı özel ad olmadığı için \'kırlangıçlar\' küçük yazılır. Diğer seçenekler kurallara uygundur.'),
  ('Aşağıdaki cümlelerin hangisinde büyük harfle yazılmayan bir yön adı bulunur?', 'Bu akşam doğuya doğru yola çıkacağız.', ['Orada Güneydoğu Anadolu Bölgesi\'ni gezdik.', 'Karadeniz kıyısına gittik.', 'Tuz Gölü\'nün çevresi çok güzeldir.'], 'Yön adları, bir bölge adının parçası olmadıkça yön anlamıyla küçük harfle yazılır.'),
  ('\'Dünya Güneş\'in çevresinde döner.\' cümlesinde \'Dünya\' ve \'Güneş\' sözcükleri neden büyük harfle başlıyor?', 'Gök cismi adı olarak özel ad sayıldıkları için', ['Cümlenin başında oldukları için', 'Bu sözcüklerin çoğul olması nedeniyle', 'Yalnız özne olduklarında büyük yazıldıkları için'], 'Gök cisimleri (Dünya, Güneş, Ay, Mars) astronomi anlamında özel ad kabul edilir. \'Dünya\' sözcüğü genel anlamda (\'dünya nimetleri\') küçük yazılır.'),
  ('\'Bayramda akrabalarımızı ziyaret ettik.\' cümlesi ile \'Kurban Bayramı\'nda akrabalarımızı ziyaret ettik.\' cümlesinde yazım farkı neden oluşmuştur?', 'Belirli bayram adı özel ad olduğundan büyük harfle yazılmıştır.', ['İkinci cümlede özne değiştiği için', 'İlk cümlede bayram sözcüğü eylem olduğu için', 'İkinci cümle soru cümlesi olduğu için, soru cümleleri büyük yazılır'], 'Belirli bayramların adı (\'Kurban Bayramı, Cumhuriyet Bayramı\') özel ad olarak büyük yazılır; genel \'bayram\' küçük yazılır.'),
  ('Atasözü ya da cümle başlayınca büyük harf kullanmanın dışında, tırnak içindeki bir sözün cümle başı için hangisi doğrudur?', 'Kendi başına cümle ise büyük harfle başlar.', ['Her zaman küçük harfle başlar.', 'Büyük harf yalnız ilk sözcüğün baş harfidir, sonraki sözcükler de büyüktür.', 'Tırnak içinde noktalama yoksa büyük harf konmaz.'], 'Doğrudan aktarılan cümleler kendi içinde bir cümle olduğu için büyük harfle başlar.'),
  ('Aşağıdaki yer adlarından hangisi büyük harfle yazılırsa özel adı oluşturmaz?', 'köy meydanı', ['Beyazıt Meydanı', 'Atatürk Caddesi', 'Kız Kulesi'], '\'Köy meydanı\' genel bir tanımdır. Belirli bir adı olan yerlerde (\'Beyazıt Meydanı\') sözcükler büyük harfle başlar.'),
  ('\'Mehmet\' özel adına yönelme eki getirilince hangi yazım doğrudur?', 'Mehmet\'e', ['Mehmed\'e', 'Mehmede', 'Mehmet\' e'], 'Özel adlarda sert ünsüz yumuşamaz ve ek kesmeyle ayrılır: \'Mehmet\'e\'. \'Mehmede\' kesmesiz yazım yanlıştır.'),
  ('\'Hükümetin 1990 yılı programı\' anlamında \'1990___ yıllar\' ifadesine \'-lı\' benzeri ek getirmek gerekirse doğru yazım hangisidir?', '1990\'lı yıllar', ['1990lı yıllar', '1990 lı yıllar', '1990 - lı yıllar'], 'Rakamlara gelen ekler kesmeyle ayrılır: \'1990\'lı\', \'1980\'ler\'.'),
  ('\'TBMM\' kısaltmasına çekim eki getirilirken ek hangi ölçüte göre belirlenir?', 'Kısaltmanın okunuşuna göre belirlenir ve kesmeyle ayrılır.', ['Kısaltmadaki son harfin yazılışına göre ek belirlenir.', 'Ek hiç getirilmez, kısaltma yalın kalır.', 'Kısaltma açılımına göre, ek kesmesiz yazılır.'], 'Kısaltmalara gelen ekler, sondaki harfin okunuşuna uygun olur ve kesme işaretiyle ayrılır: \'TBMM\'nin\' (\'em\' okunduğu için \'nin\').'),
  ('\'Londra\' ve \'Paris\' sözcüklerine ilgi eki \'-ın/-in\' getirildiğinde doğru yazım hangi seçenekte vardır?', 'Londra\'nın, Paris\'in', ['Londranın, Parisin', 'Londra\'nin, Paris\'ın', 'Londra\'nın, Paris\'ın'], 'Kesme işareti özel adla ek arasına konur; ünlü uyumu son ünlüye göre belirlenir: \'Londra\'nın\' (a → ın), \'Paris\'in\' (i → in).'),
  ('\'Atatürk\' özel adı ile \'Atatürkçü\' sözcüğü arasında kesme işareti yönünden nasıl bir fark vardır?', '\'Atatürk\'ün\' çekim eki aldığı için kesmeli, \'Atatürkçü\' yapım eki aldığı için kesmesizdir.', ['İkisi de çekim eki alır; ikisi de kesmelidir.', 'İkisi de yapım eki alır; ikisi de kesmesizdir.', '\'Atatürkçü\' kesmelidir; \'Atatürk\'ün\' ise kesmesizdir, çünkü sözcük özel addır.'], 'Çekim ekleri özel adı kesmeyle ayırır; yapım ekleriyle türeyen sözcüklerde kesme kullanılmaz.'),
  ('\'Ayşe + ile\' birleşiminin kısaltılmış doğru yazımı hangisidir?', 'Ayşe\'yle', ['Ayşeyle', 'Ayşe\'ile', 'Ayşe \'yle'], '\'İle\' kısaltılınca bitişir; özel ad olduğu için kesmeyle ayrılır ve kaynaştırma \'y\' gelir: \'Ayşe\'yle\'.'),
  ('\'Ankaralı\', \'İzmirli\' ve \'Konyalılar\' sözcüklerinde kesme işareti kullanılmamasının nedeni nedir?', '\'-lı/-li\' yapım ekidir; yapım ekleri özel adlardan kesmeyle ayrılmaz.', ['Bu sözcükler özel ad olmadıkları için', 'Kesme işareti yalnız tek heceli özel adlarda kullanıldığı için', 'Bu sözcüklerin son harfi ünlü olduğu için'], 'Özel addan yapım ekiyle türemiş sözcüklerde kesme işareti kullanılmaz.'),
  ('Aşağıdaki sözcüklerden hangisi kesme işareti almaz?', 'Mehmetçik', ['Mehmet\'in', 'Mehmet\'e', 'Mehmet\'ten'], '\'-çik\' küçültme yapım ekidir. \'Mehmetçik\' kesmesiz yazılır; diğerleri çekim eki aldıkları için kesmelidir.'),
  ('\'Kalem, defter, silgi ve benzeri\' anlamındaki ifade, cümle sonunda kısaltılırsa hangisi doğru yazılır?', 'Kalem, defter, silgi vb.', ['Kalem, defter, silgi vb', 'Kalem, defter, silgi v.b.', 'Kalem, defter, silgi, vb..'], '\'Ve benzeri\' için \'vb.\' kısaltması kullanılır; sonunda nokta bulunur. Cümle sonunda ikinci bir nokta konmaz.'),
  ('Aşağıdaki ölçü birimi yazımlarından hangisi doğrudur?', 'Sınıf 5 m uzunluğunda.', ['Sınıf 5 m. uzunluğunda.', 'Sınıf 5 metre. uzunluğunda.', 'Sınıf 5 mt. uzunluğunda.'], 'Ölçü birimleri (m, km, kg, cm) küçük harfle ve nokta konmadan yazılır.'),
  ('\'Ahmet Cemal Yılmaz\' adı kısaltılarak yazılırsa hangisi TDK kuralına uygun olur?', 'A. C. Yılmaz', ['A.C. YILMAZ', 'AC Yılmaz', 'A C Yılmaz.'], 'Kişi adlarının kısaltılan kısmı büyük harf ve nokta ile yazılır; soyadı açık kalır: \'A. C. Yılmaz\'.'),
  ('\'Türk Hava Yolları\' için kullanılan \'THY\' kısaltmasına ilgi eki gelirse doğru yazım hangisidir?', 'THY\'nin', ['THY\'ın', 'THYnin', 'T.H.Y.\'nin'], 'Kısaltmalara gelen ek, okunuşa göre seçilir ve kesmeyle ayrılır. \'Y\' harfi \'ye\' okunduğundan ek \'nin\' olur.'),
  ('Aşağıdaki cümlelerin hangisinde kısaltmalar kuralına aykırı yazım vardır?', 'Ahmet Bey 12 kg. şeker aldı.', ['Dr. Ayşe Hanım hastaları görüyor.', 'TDK yeni sözlüğü yayımladı.', 'Yeni bina 30 m yüksekliğinde.'], '\'kg\' bir ölçü birimi simgesidir ve nokta almaz: \'12 kg\'.'),
  ('Beklenmedik güzel bir haber ya da armağan için kullanılan sözcüğün doğru yazımı hangisidir?', 'sürpriz', ['sürpiriz', 'sürpirz', 'sürprizz'], '\'Sürpriz\' sözcüğü ünlü türetmeden yazılır; \'sürpiriz\' yanlıştır.'),
  ('Deney yapılan bilimsel araştırma odasını anlatan sözcüğün TDK\'ye göre doğru yazımı hangisidir?', 'laboratuvar', ['labaratuvar', 'laboratuar', 'laboratuvvar'], 'TDK\'ye göre doğru biçim \'laboratuvar\'dır; \'labaratuvar\' ise sık yapılan bir hatadır.'),
  ('Aşağıdaki sözcüklerden hangisinin yazımı TDK\'ye göre doğrudur?', 'eşofman', ['eşörman', 'eşofmann', 'eşöfman'], 'Sözcük \'eşofman\' biçiminde yazılır; \'eşörman\' veya \'eşöfman\' yanlıştır.'),
  ('Araç egzozu için doğru yazım hangisidir?', 'egzoz', ['eksoz', 'egzzoz', 'egsoz'], 'TDK\'ye göre \'egzoz\' yazımı doğrudur.'),
  ('Defter, kalem gibi yazı gereçlerinin satıldığı dükkânı anlatan sözcüğün doğru yazımı hangisidir?', 'kırtasiye', ['kırtasiyye', 'kırdasiye', 'kırtaşiye'], 'Doğru yazım \'kırtasiye\'dir.'),
  ('Aşağıdaki sözcüklerden hangisi yanlış yazılmıştır?', 'sandwiç', ['sandviç', 'ağabey', 'pardösü'], 'Doğru yazımı \'sandviç\'tir; \'sandwiç\' yazımı TDK\'ye uygun değildir.'),
  ('Kış aylarında yağan beyaz örtü ile kazanç anlamındaki sözcüğü yazıda birbirinden ayıran işaret hangisidir?', 'Kazanç anlamındaki sözcükte uzatma işareti (şapka) bulunur: \'kâr\'.', ['Kar sözcüğüne vurgu işareti konur: \'kár\'.', 'Kazanç sözcüğü büyük harfle başlar: \'Kar\'.', 'İkisi de aynı yazılır, anlam bağlamdan çıkarılır, işaret konmaz.'], 'Eş sesli sözcükleri ayırmak için şapka kullanılır: \'kâr\' (kazanç), \'kar\' (yağış).'),
  ('\'Bu sınıfta on ___ sandalye var.\' boşluğa sayı birimi anlamındaki sözcük gelecektir. Doğru yazım hangisidir?', 'adet', ['âdet', 'âdat', 'âdit'], 'Sayı birimi anlamında \'adet\' şapkasız yazılır. Gelenek anlamındaki \'âdet\' ise şapkalıdır.'),
  ('\'Kayalık ___ kenarına oturdu.\' boşluğa \'uçurum, dik yamaç\' anlamındaki sözcük gelirse doğru yazım hangisi olur?', 'yar', ['yâr', 'yâ', 'yâhr'], '\'Yar\' uçurum demektir ve şapkasızdır. \'Yâr\' ise sevgili anlamında şapkalı yazılır.'),
  ('Aşağıdaki sözcüklerden hangisinin yazımında şapka işareti kullanılması gerekir?', 'dükkân', ['pencere', 'televizyon', 'şeker'], '\'Dükkân\' sözcüğünde \'k\' ünsüzünden sonra gelen \'a\' ünlüsü şapkayla gösterilir; diğerlerinde şapka gerekmez.'),
  ('Şapka işaretinin yazımdaki görevleri için aşağıdakilerden hangisi doğrudur?', 'Bazı sözcüklerde ünlüyü uzatır; k, g, l ünsüzlerinden sonra a, u ünlülerini inceltir.', ['Yalnız vurgulu heceyi göstererek okunuşu belirler.', 'Sözcüğün sonunda ünlü düşmesi olduğunu gösterir.', 'Sözcüğün bileşik olduğunu gösterir, parçaları birbirinden ayırır.'], 'Şapka (^) uzatma ve inceltme işaretidir; \'kâğıt, ahlâk, kâr\' sözcüklerinde bu işlev görülür.'),
  ('Sert ünsüz benzeşmesine uygun yazılmış tek sözcük hangisidir?', 'sokakta', ['kitapda', 'çiçekde', 'ağaçda'], '\'k, p, ç\' sert ünsüzlerinden sonra \'da\' eki \'ta\' olur: \'sokakta\' doğrudur.'),
  ('Sert ünsüzlerin ezber cümlesi olan \'fıstıkçı şahap\' içinde yer almayan bir harf aşağıdakilerden hangisidir?', 'm', ['f', 'k', 'ş'], 'Sert ünsüzler f, s, t, k, ç, ş, h, p\'dir; \'m\' yumuşak ünsüzdür.'),
  ('\'Toplantıya ___ gelmedi.\' boşluğa \'hiç + kimse\' getirilirse doğru yazım hangisi olur?', 'hiç kimse', ['hiçkimse', 'hiç-kimse', 'hiç kimse\''], '\'Hiç kimse\' ayrı yazılır; \'hiçbir\' ise bitişik yazılır.'),
  ('\'Hastalığım ___ çabuk geçmez sanırım.\' cümlesinde, \'o kadar\' ve \'şu kadar\' gibi yakın gösterme belirtecinin doğru yazımı hangisidir?', 'bu kadar', ['bukadar', 'bu-kadar', 'bu kadar\''], '\'Bu kadar, o kadar, şu kadar\' ayrı yazılır.'),
  ('\'___ misafirler zamanında gelmedi.\' boşluğuna, \'maalesef\' anlamlı üç sözcüklü ifade getirilirse doğru yazım hangisidir?', 'Ne yazık ki', ['Neyazıkki', 'Ne yazıkki', 'Ne-yazık-ki'], '\'Ne yazık ki\' üç ayrı sözcükten oluşan bir ifadedir; \'ki\' bağlaç olarak ayrı yazılır.'),
  ('\'Matematik ___ fizik sınavına girmek zorunda.\' boşluğa tek sözcükle yazılan seçenek bağlacı getirilirse hangisi doğru olur?', 'yahut', ['ya hut', 'yâhut', 'ya-hut'], '\'Yahut\' tek sözcüktür ve bitişik yazılır; \'ya da\' ile eş anlamlıdır.'),
  ('\'Gelir ___ gelmez bilemiyorum.\' cümlesinde \'ya da\' yerine kullanılan \'veya\' sözcüğünün yazımı için hangisi doğrudur?', '\'Veya\' tek sözcüktür ve bitişik yazılır.', ['\'Ve ya\' iki sözcüktür ve ayrı yazılır.', '\'Veya\' kısa çizgiyle yazılır: \'ve-ya\'.', '\'Veya\' büyük harfle başlamalıdır.'], '\'Veya\' tek bir bağlaçtır; \'veyahut\' da bitişik yazılır.'),
  ('\'Ya yarın ya da cuma gideriz.\' cümlesindeki \'ya ... ya da\' için hangisi doğrudur?', 'Tekrarlı bağlaç grubudur; \'ya da\' ayrı yazılır.', ['\'Yada\' bitişik yazılmalıdır.', '\'Ya ya da\' tek sözcük olarak yazılmalıdır.', 'İkinci \'ya\' bağlaç değil ektir.'], '\'Ya ... ya da\' seçenek bağlacıdır. \'Ya\' ve \'da\' ayrı yazılır.'),
  ('\'Ne ev ne de araba satın alabildi.\' cümlesindeki \'ne de\' bağlaç grubu için hangisi doğrudur?', 'Üç sözcük değil iki sözcüktür ve \'de\' ayrı yazılır.', ['\'Nede\' bitişik yazılmalıdır.', '\'Ne de\' sözcükleri bitişik, \'ne\' ayrı yazılır.', 'Bu bağlaç hiçbir zaman ayrı yazılmaz.'], '\'Ne ... ne de\' olumsuz bağlaç grubudur; \'de\' bağlaçtır, ayrı yazılır.'),
  ('\'Senin kadar çalıştım.\' ifadesinde \'kadar\' sözcüğünün yazımı için hangisi doğrudur?', '\'Kadar\' edattır ve ayrı yazılır.', ['\'Kadar\' bitişik yazılır: \'seninkadar\'.', '\'Kadar\' kısa çizgiyle yazılır: \'senin-kadar\'.', '\'Kadar\' yalnız sayılardan sonra ayrı yazılır.'], '\'Kadar\' edatı kendinden önceki sözcükten ayrı yazılır.'),
  ('Aşağıdaki cümlelerden hangisinde \'ile\' sözcüğü yanlış yazılmıştır?', 'Kalem le yazdım.', ['Kalemle yazdım.', 'Kalem ile yazdım.', 'Arkadaşımla yürüdüm.'], '\'İle\' ayrı yazılabilir ya da \'-le/-la\' biçiminde bitişik yazılır; \'kalem le\' biçimi yanlıştır.'),
  ('\'Annem ile babam\' ifadesi kısaltılarak yazıldığında doğru biçim hangisidir?', 'Annemle babam', ['Annem\'le babam', 'Anneme le babam', 'Annemle\'babam'], '\'İle\' kısaltılarak sözcüğe eklenirken bitişik yazılır; genel adlarda kesme işareti kullanılmaz.'),
  ('Hastalık döneminde dayanmayı anlatan \'Biraz ___ , her şey düzelecek.\' cümlesinde boşluğa hangi yazım gelmelidir?', 'sabret', ['sabır et', 'sabıret', 'sabirret'], '\'Sabır + et-\' birleşirken ses düşmesi olur: \'sabretmek\' bitişik yazılır.'),
  ('\'Bu öneriyi hiç düşünmeden ___.\' boşluğa \'ret + etmek\' fiilinin geçmiş zamanı gelirse TDK\'ye uygun yazım hangisidir?', 'reddetti', ['ret etti', 'redetti', 'reddedti'], '\'Ret\' sözcüğü \'etmek\' ile birleşirken \'d\' ünsüzü ikizleşir ve sözcük bitişik yazılır: \'reddetmek\'.'),
  ('\'Af\' + \'etmek\' birleşiminde ses olayı nasıl yazıya yansımıştır?', '\'f\' ikizleşir ve sözcük bitişik yazılır: \'affetmek\'.', ['Ses olayı yoktur; \'af etmek\' ayrı yazılır.', '\'f\' düşer ve \'aetmek\' olur.', 'Araya kısa çizgi girer: \'af-etmek\'.'], 'Arapça kökenli \'af\' sözcüğü \'etmek\' ile birleşince \'f\' ikizleşir: \'affetmek\'.'),
  ('\'Babasını hiç ___ gitti.\' cümlesinde boşluğa \'terk + etmek\' fiilinin ulaç biçimi getirilirse hangi yazım doğrudur?', 'terk etmeden', ['terketmeden', 'terk-etmeden', 'terk etmedenn'], '\'Terk\' ünsüzle bittiği hâlde ses olayı olmadığından \'etmek\' ayrı yazılır.'),
  ('\'Müdür personele açık bir şekilde ___.\' cümlesindeki \'emir\' + \'etmek\' fiilinin doğru yazımı hangisidir?', 'emretti', ['emir etti', 'emiretti', 'emr etti'], '\'Emir\' + \'etmek\' birleşirken ünlü düşer: \'emretmek\' bitişik yazılır.'),
  ('\'Çocuk kalabalıkta ___.\' cümlesinde \'kayıp\' + \'olmak\' birleşimiyle kurulan fiilin doğru yazımı hangisidir?', 'kayboldu', ['kayıp oldu', 'kayıpoldu', 'kaybooldu'], '\'Kayıp\' ve \'olmak\' birleşirken ses düşmesi olur ve sözcük bitişik yazılır: \'kaybolmak\'.'),
  ('Aşağıdaki bileşik fiillerden hangisi yanlış yazılmıştır?', 'kabuletmek', ['kabul etmek', 'reddetmek', 'affetmek'], '\'Kabul\' sözcüğü \'etmek\' ile birleşirken ses olayı geçirmez; \'kabul etmek\' ayrı yazılır.'),
  ('\'Bozulan arabayı usta tamir etti.\' cümlesindeki bileşik fiil için hangisi doğrudur?', 'Ses olayı olmadığı için \'tamir etmek\' ayrı yazılır.', ['Ünlü düştüğü için \'tamretmek\' bitişik yazılır.', 'Ünsüz ikizleştiği için \'tamirretmek\' yazılır.', 'Araya kısa çizgi gelir: \'tamir-etmek\'.'], '\'Tamir etmek\' bileşiğinde ses olayı bulunmaz, bu nedenle ayrı yazılır.'),
  ('Saatin rakamla yazımında saat ile dakika arasına hangi işaret konur?', 'Nokta', ['Virgül', 'Noktalı virgül', 'Eğik çizgi'], 'TDK\'ye göre saat yazımında saat ile dakika nokta ile ayrılır: \'14.30\'.'),
  ('Bir milyon iki yüz elli bin sayısı rakamla yazılırken binlik basamakları ayırmak için hangisi kullanılır?', '1.250.000', ['1,250,000', '1 250,000', '1\'250\'000'], 'Türkçede binlik basamaklar nokta ile ayrılır: \'1.250.000\'.'),
  ('Madde numaralarında kullanılan \'1.\' ve \'2.\' gösterimi için hangisi doğrudur?', 'Rakamdan sonra nokta konur.', ['Rakamdan sonra virgül konur.', 'Rakamdan sonra iki nokta konur.', 'Rakamdan sonra işaret konmaz.'], 'Maddeler sayıyla sıralanırken rakamın yanına nokta konur.'),
  ('Aşağıdaki cümlelerin hangisinde nokta yanlış kullanılmıştır?', 'Ankara. Türkiye\'nin başkentidir.', ['Dr. Ali ameliyata girdi.', 'Sınav 14.30\'da başlayacak.', 'Saat 5\'te buluşalım.'], 'Cümlenin ortasında, anlam bütünlüğünü bölen nokta kullanılamaz.'),
  ('\'Çocuk ne zaman geleceğini sordu\' cümlesinin sonuna hangi işaret konmalıdır?', 'Nokta', ['Soru işareti', 'Ünlem', 'İki nokta'], 'Dolaylı soru içeren bildirme cümlesi nokta ile biter.'),
  ('\'Bu konu, bence, tartışmaya değmez.\' cümlesindeki virgüllerin işlevi nedir?', 'Ara sözü cümleden ayırmak', ['Sıralı cümleleri ayırmak', 'Eş görevli sözcükleri sıralamak', 'Hitabı belirtmek'], '\'Bence\' ara sözdür; iki yanına virgül konur.'),
  ('\'Çalışkan bir öğrenciydi ama bu sınavda başarısız oldu.\' cümlesinde \'ama\' bağlacından önce nasıl bir işaret gerekir?', 'Virgül', ['Nokta', 'İki nokta', 'Hiçbir işaret'], '\'Ama, fakat, lakin\' gibi karşıtlık bağlaçlarından önce virgül konur.'),
  ('Mektuplarda yer ve tarih bilgisinin yazımı için hangisi doğrudur?', 'Ankara, 12 Mayıs 2019', ['Ankara. 12 Mayıs 2019', 'Ankara; 12 Mayıs 2019', 'Ankara: 12 Mayıs 2019'], 'Yer adı ile tarih arasına virgül konur.'),
  ('\'Kırmızı, mavi ve yeşil boyalar aldım.\' cümlesinde \'ve\' bağlacından önce virgül konmamıştır. Bu durum neyi gösterir?', '\'Ve\' bağlacı öğeyi zaten bağladığı için önüne virgül konmaz.', ['Cümlede hata olduğunu', '\'Ve\' sözcüğünün sıfat olduğunu', 'Cümlenin soru anlamı taşıdığını'], 'Eş görevli öğelerin sonuncusundan önce \'ve\' varsa ondan önce virgül gerekmez.'),
  ('Aşağıdaki cümlelerde \'çünkü\' bağlacından önce nasıl bir noktalama beklenir? \'Sınava gitmedi çünkü hastaydı.\'', 'Virgül veya noktalı virgül konabilir.', ['Hiçbir işaret konamaz.', 'Soru işareti konur.', 'Üç nokta konur.'], 'Neden bildiren \'çünkü\' öncesinde, cümleyi ayırmak için virgül ya da noktalı virgül konur.'),
  ('Aşağıdaki cümlelerin hangisinde noktalı virgül ayrı yargıları, içinde virgül bulunan öğelerle ayırmak için doğru kullanılmıştır?', 'Ali, Ankara\'dan; Veli, İzmir\'den; Ayşe ise Bursa\'dan geldi.', ['Ali, Ankara\'dan, Veli, İzmir\'den, Ayşe ise Bursa\'dan geldi.', 'Ali, Ankara\'dan. Veli, İzmir\'den. Ayşe ise Bursa\'dan geldi.', 'Ali, Ankara\'dan: Veli, İzmir\'den: Ayşe ise Bursa\'dan geldi.'], 'İçinde virgül bulunan öğeler sıralanırken ayrım için noktalı virgül kullanılır.'),
  ('\'Hava soğuktu; yine de yürüyüşe çıktık.\' cümlesinde noktalı virgülün işlevi nedir?', 'Birbirine yakın anlamlı iki bağımsız cümleyi ayırmak', ['Ara sözü ayırmak', 'Eş görevli sözcükleri sıralamak', 'Hitabı belirtmek'], 'Anlamca birbiriyle ilgili ama bağımsız iki cümle noktalı virgülle ayrılır.'),
  ('Aşağıdakilerden hangisinde noktalı virgül yanlış yerde kullanılmıştır?', 'Ali; okula gitti.', ['Hava güzeldi; çocuklar oynadı.', 'Kitabı okudum; çok beğendim.', 'Yağmur dindi; yola çıktık.'], 'Özne ile yüklem arasında noktalı virgül kullanılamaz.'),
  ('Noktalı virgül ile virgülün arasındaki duraklama farkı için hangisi doğrudur?', 'Noktalı virgül virgülden daha uzun, noktadan daha kısa bir duraklama gösterir.', ['Noktalı virgül, virgülden daha kısa bir duraklama gösterir.', 'Noktalı virgül ile virgül aynı duraklamayı gösterir.', 'Noktalı virgül noktadan daha uzun bir duraklama gösterir.'], 'Duraklama sırası: virgül < noktalı virgül < nokta.'),
  ('Aşağıdaki cümlelerin hangisinde iki nokta açıklama için doğru kullanılmıştır?', 'Şunu unutma: yarın sınav var.', ['Şunu: unutma yarın sınav var.', 'Şunu unutma yarın: sınav var.', 'Şunu unutma; yarın: sınav var.'], 'Açıklanacak ifadeden sonra iki nokta konur ve açıklama devam eder.'),
  ('Aşağıdaki cümlelerden hangisinde iki nokta gereksiz yere kullanılmıştır?', 'Dün Ali: okula gitti.', ['Ahmet: Yarın görüşürüz.', 'Şu şehirleri gezdim: Edirne, Kars, Van.', 'Not: Kitaplar teslim edilecek.'], 'Özne ile yüklem arasında iki nokta kullanılmaz.'),
  ('Alıntılanan bir metinde atlanan bölümü göstermek için hangisi kullanılır?', '(...) veya ... işareti', ['Tek nokta ve ünlem birlikte', 'İki nokta', 'Ünlem'], 'Alıntıda çıkarılan kısım üç nokta ile gösterilir.'),
  ('Aşağıdaki cümlelerin hangisinde üç nokta doğru kullanılmıştır?', 'Bilmiyorum... belki gelir.', ['Bilmiyorum.... belki gelir.', 'Bilmiyorum.. belki gelir.', 'Bilmiyorum, ... belki gelir.'], 'Üç nokta tam üç tane yazılır; dörtlü ya da ikili nokta yazımı yanlıştır.'),
  ('Aşağıdaki cümlelerin hangisinde üç nokta bir sözün tam söylenmesi istenmediğini anlatır?', 'Bu adam tam bir ...!', ['Bu adam tam bir ....!', 'Bu adam tam bir ..!', 'Bu adam tam bir .!'], 'Kaba ya da söylenmesi istenmeyen sözcük yerine üç nokta kullanılır.'),
  ('\'Sonra... sonra neler olduğunu bilmiyorum.\' cümlesinde üç noktanın işlevi nedir?', 'Duraksamayı ve tereddüdü göstermek', ['Soru sormak ve yanıt beklemek', 'Ünlem belirtmek', 'Açıklama yapmak'], 'Üç nokta konuşmadaki duraksama ve tereddüdü de gösterebilir.'),
  ('Aşağıdaki gösterimlerden hangisinde tarihin kesin olarak bilinmediği belirtilmiştir?', 'Ahmet Bey (1850?-1920)', ['Ahmet Bey (1850-1920)', 'Ahmet Bey (1850/1920)', 'Ahmet Bey (1850 : 1920)'], 'Kesin olmayan tarihten sonra soru işareti konur.'),
  ('\'Çok (?) akıllı bir öğrenci olduğunu söylüyordu.\' cümlesinde parantez içindeki soru işareti neyi gösterir?', 'Söylenene kuşku ya da alay', ['Cümlenin soru olduğunu gösterdiğini', 'Yazı hatası olduğunu', 'Tarihin bilinmediğini'], 'Parantez içinde soru işareti, söylenene güvensizlik ya da alay anlamı katar.'),
  ('Aşağıdaki cümlelerden hangisinde soru işareti yanlış kullanılmıştır?', 'Ne kadar güzel bir manzara?', ['Hangi kitabı okudun?', 'Nereye gidiyorsun?', 'Kaçta buluşacağız bu akşam?'], '\'Ne kadar güzel bir manzara\' bir ünlem cümlesidir; soru işareti değil ünlem kullanılır.'),
  ('\'Gelmedi mi?\' cümlesinin soru işaretinden önceki soru ekiyle ilgili doğru bilgi hangisidir?', 'Soru eki ayrı yazılır, cümle soru işaretiyle biter.', ['Soru eki bitişik yazılır, cümle noktayla biter.', 'Soru eki ayrı yazılır, cümle noktayla biter.', 'Soru eki bitişik yazılır, cümle soru işaretiyle biter.'], 'Soru eki ayrı yazılır ve cümle soru işaretiyle bitirilir.'),
  ('Aşağıdaki cümlelerden hangisinde cümle soru gibi görünse de sonuna ünlem konmalıdır?', 'Ne güzel bir gün bu', ['Sen buraya neden geldin', 'Kim bu kitabı aldı', 'Saat kaç oldu'], 'Hayranlık bildiren ünlem cümlesinin sonuna ünlem işareti konur.'),
  ('\'Bu işi sen yapmışsın (!)\' ifadesindeki parantez içi ünlem neyi gösterir?', 'Alay ya da şaşkınlık', ['Cümlenin soru olduğunu', 'Açıklama yapıldığını', 'Alıntı yapıldığını'], 'Parantez içinde ünlem, alay veya şaşkınlığı gösterir.'),
  ('Birbirini izleyen ünlemler \'Yaşasın! Yaşasın! Yaşasın!\' için hangisi doğrudur?', 'Her ünlem ayrı işaretle biter ve sonraki söz büyük harfle başlar.', ['Üçü de virgülle ayrılır ve tek cümle sayılır.', 'Sonlarında işaret bulunmaz, bunlar tek cümle sayılır.', 'Üç ünlem tek ünlem olarak yazılır ve sonrakiler küçük harfle başlar.'], 'Tekrarlanan ünlemler art arda gelirse her biri kendi ünlem işaretini alır.'),
  ('\'Bu "akıllı" hareketi kimse beklemiyordu.\' cümlesinde \'akıllı\' sözcüğünün tırnak içine alınması neyi gösterir?', 'Sözcüğün alaycı ya da özel bir anlamda kullanıldığını', ['Sözcüğün yabancı kökenli olduğunu', 'Sözcüğün ek aldığını', 'Sözcüğün büyük harfle başlayacağını bildirir'], 'Tırnak işareti, sözcüğün alay veya özel anlam taşıdığını vurgulamak için de kullanılır.'),
  ('"Gelmeyeceğim." dedi. cümlesinde tırnak içindeki cümlenin noktası nerede yer alır?', 'Tırnağın içinde, kapanış tırnağından önce', ['Tırnağın dışında, kapanış tırnağından sonra', 'Hiç konmaz', 'Hem içte hem dışta konur'], 'Tırnak içindeki cümlenin noktası kapanış tırnağından önce gelir.'),
  ('Bir yazıda dört cümleden birinde sıradan bir sözcük, hiçbir özel anlamı yokken tırnağa alınmıştır. O cümle hangisidir?', 'Bahçedeki "çiçekler" çok güzel açmış.', ['Ali bana "Geliyorum." dedi.', 'Bu "zekice" davranışı hiç sevmedim.', '"Savaş ve Barış" kitabını dün okudum.'], '\'Çiçekler\' sıradan bir sözcüktür; alay ya da özel anlam yoksa tırnak içine alınmaz.'),
  ('\'Kâtip\' sözcüğü hakkında verilen \'Kâtip sözcüğü yazıcı demektir.\' cümlesinde sözcüğü ayrıca vurgulamak için hangi işaret kullanılabilir?', 'Tırnak işareti', ['Ünlem işareti', 'İki nokta üst üste', 'Soru işareti'], 'Anlamı açıklanan sözcükler tırnak içine alınır.'),
  ('Maddeleri harfle sıralarken \'a)\', \'b)\' gibi gösterimde yay ayracın görevi nedir?', 'Sıra bildiren harf ya da rakamdan sonra kapama işareti olmak', ['Alıntıyı kapatmak ve bitirmek', 'Cümleyi bitirmek', 'Bağlaç yerine geçmek'], 'Maddeler \'a)\' veya \'1)\' biçiminde yazılırken kapanış ayracı kullanılır.'),
  ('Aşağıdaki cümlelerin hangisinde yay ayraç doğru kullanılmıştır?', 'Yazar (ünlü bir roman yazarı) bugün imza günü yapacak.', ['Yazar ünlü bir roman yazarı) bugün imza günü yapacak.', 'Yazar (ünlü bir roman yazarı bugün imza günü yapacak.', 'Yazar ((ünlü bir roman yazarı) bugün imza günü yapacak.'], 'Yay ayraç açıldıktan sonra mutlaka kapatılır.'),
  ('Alıntı yapan bir yazar, kendi eklediği açıklamayı alıntının içine yazmak istiyor. Bu açıklama hangi işaretle gösterilebilir?', 'Köşeli ayraç', ['Üç nokta', 'Tırnak içinde tırnak', 'Kısa çizgi'], 'Alıntıya sonradan eklenen açıklamalar köşeli ayraç içine alınır.'),
  ('Aşağıdaki örneklerden hangisinde köşeli ayraç doğru kullanılmıştır?', '"Çocuk [Ali] bahçeye çıktı."', ['"Çocuk <Ali> bahçeye çıktı."', '"Çocuk {Ali} bahçeye çıktı."', '"Çocuk (Ali bahçeye çıktı,."'], 'Alıntıya araya sokulan açıklama köşeli ayraç içinde verilir.'),
  ('\'Ankara-İstanbul\' ve \'Türk-Alman\' gibi yazımlarda kısa çizginin görevi nedir?', 'İki yer, kişi ya da kavram arasındaki ilişkiyi bildirmek', ['Alıntıyı açmak ve kapamak', 'Cümleyi bitirmek', 'Ünlüyü uzatmak'], 'Kısa çizgi iki sözcük, yer ya da sayı arasındaki ilişkiyi göstermek için kullanılır.'),
  ('\'-lar\' ve \'-ler\' gibi çokluk ekleri tek başına gösterilirken nasıl yazılır?', 'Önüne kısa çizgi konarak', ['Tırnak içinde yalın biçimde', 'Yay ayraç içinde', 'Eğik çizgiyle'], 'Ek tek başına anılırken öncesine kısa çizgi konur: \'-lar, -ler\'.'),
  ('Satır sonunda sözcüğün bölünmesi için hangisi doğrudur?', 'Sözcük heceden bölünür; tek harf satır sonunda bırakılmaz.', ['Sözcük herhangi bir harften bölünebilir, hece aranmaz.', 'Sözcük hiçbir zaman bölünemez.', 'Sözcük ünlüden sonra her zaman bölünür.'], 'Satır sonunda sözcükler hecelerine uygun bölünür; tek harf satırda bırakılmaz.'),
  ('Aşağıdaki cümlelerden hangisinde kısa çizgi uygunsuz kullanılmıştır?', 'Dün-akşam sinemaya gittik.', ['Türk-Alman ilişkileri geliştirildi.', 'İstanbul-Ankara hızlı treni açıldı.', 'Fiil kökü: git-'], '\'Dün akşam\' sıradan bir öbektir; araya kısa çizgi konmaz.'),
  ('\'Ali — benim en yakın arkadaşım — bugün geliyor.\' cümlesinde uzun çizgilerin görevi nedir?', 'Cümle içindeki ara sözü ayırmak', ['Konuşma başlatmak ve bitirmek', 'Sayı aralığı göstermek', 'Kısaltma yapmak'], 'İki uzun çizgi arasındaki bölüm, cümlenin akışını bölen ara söz ya da açıklamadır.'),
  ('Aşağıdaki diyalog satırlarından hangisinde konuşma çizgisi doğru kullanılmıştır?', '— Yarın gelir misin? diye sordu.', ['- Yarın gelir misin? diye sordu.', '— yarın gelir misin diye sordu', '– Yarın gelir misin? diye sordu ..'], 'Konuşma çizgisinden sonra boşluk bırakılır, konuşma büyük harfle başlar.'),
  ('Adreslerde \'Çankaya/Ankara\' yazımında eğik çizgi hangi işlevi görür?', 'İlçe ile il adını ayırmak', ['Sayı aralığı belirtmek ve ayırmak', 'Konuşmayı başlatmak', 'Soruyu belirtmek'], 'İlçe ve il adları eğik çizgiyle birbirinden ayrılır.'),
  ('Aşağıdaki örneklerden hangisinde eğik çizgi alternatif belirtmek için doğru kullanılmıştır?', 'Öğrenci/öğretmen girişi', ['Öğrenci\\öğretmen girişi', 'Öğrenci:öğretmen girişi', 'Öğrenci ; öğretmen girişi'], 'Alternatifleri göstermek için ileri yönlü eğik çizgi kullanılır.'),
  ('Aşağıdaki sayılardan hangisi Türkçe yazım kurallarına uygun olarak yazılmıştır?', '1.234,56', ['1,234.56', '1.234.56', '1,234,56'], 'Türkçede binlik ayırıcı nokta, ondalık ayırıcı virgüldür: 1.234,56.'),
  ('\'Yüzde on iki buçuk\' ifadesinin rakamla doğru yazımı hangisidir?', '%12,5', ['12,5%', '%12.5', '12.5 %'], 'Yüzde işareti rakamın önüne bitişik yazılır; ondalık virgülle gösterilir.'),
  ('\'Toplantı saat on dörtte başlayacak.\' cümlesi rakamla yazılırsa hangi biçim TDK\'ye uygundur?', 'Toplantı saat 14.00\'te başlayacak.', ['Toplantı saat 14:00\'te başlayacak.', 'Toplantı saat 14,00te başlayacak.', 'Toplantı saat 14 00\'te başlayacak mı.'], 'TDK, saati ve dakikayı ayırmak için noktayı kullanır; sayıya gelen ek kesmeyle ayrılır.'),
  ('\'İki yüz elli gram\' ifadesi rakam ve simgeyle nasıl yazılır?', '250 g', ['250 g.', '250 gr.', '250-g'], 'Ölçü birimleri simge ile ve nokta konmadan yazılır: \'250 g\'.'),
  ('Aşağıdaki cümlelerin hangisinde tarih yazımı TDK\'ye uygundur?', 'Sınav 15 Haziran 2025 Pazar günü yapılacak.', ['Sınav on beş haziran 2025 pazar günü yapılacak.', 'Sınav 15-Haziran-2025 Pazar günü yapılacak.', 'Sınav 15 Haziran, 2025 Pazar günü yapılacak.'], 'Belirli bir tarih bildirildiğinde ay ve gün adları büyük harfle başlar.'),
  ('\'Elli lira\' parasının simgeyle yazımı hangisidir?', '50 TL', ['50 TL.', 'TL 50', '50 T.L'], 'Para birimi rakamdan sonra, aralarında boşluk bırakılarak ve noktasız yazılır.'),
  ('Aşağıdaki başlıklardan hangisinde noktalama hatası vardır?', 'Atatürk İlkeleri ve İnkılapları.', ['Atatürk İlkeleri ve İnkılapları', 'Hayatın Anlamı Nedir?', 'Mutluluk'], 'Başlık sonuna nokta konmaz.'),
  ('Metin içinde alt başlıklar yazılırken en uygun yaklaşım hangisidir?', 'Alt başlıkların sonunda nokta bulunmaz ve düzen tutarlı olur.', ['Alt başlıkların tümünün sonuna nokta konur ve büyük harfle başlanır.', 'Yalnız ilk alt başlığa nokta konur.', 'Alt başlıklar cümle içine yerleştirilir.'], 'Başlıklarda olduğu gibi alt başlıklara da nokta konmaz.'),
  ('\'Sevgili Ayşe\' hitabından sonra gelen satırın ilk harfi için hangisi doğrudur?', 'Yeni satırda büyük harfle başlar.', ['Küçük harfle başlar ve satır başı olmaz.', 'Hep büyük harflerle yazılır.', 'Önüne iki nokta konur.'], 'Hitap satırından sonra gelen metin yeni bir satırda büyük harfle başlar.'),
  ('Bir dilekçede yer ve tarihin doğru yazımı hangisidir?', 'Ankara, 20 Mayıs 2022', ['Ankara. 20 Mayıs 2022', 'Ankara; 20 mayıs 2022', 'Ankara: 20 mayıs 2022.'], 'Yer ile tarih arasında virgül konur; ay adı büyük harfle başlar.'),
  ('Aşağıdaki cümlelerden hangisinde mektup noktalamasında hata vardır?', 'Sevgili Ayşe.', ['Sevgili Ayşe,', 'Sayın Müdürüm,', 'Değerli Öğretmenim,'], 'Hitaptan sonra nokta değil virgül konur.'),
  ('\'Ali, "Yarın geleceğim." dedi.\' cümlesinde tırnaktan sonra gelen \'dedi\' sözcüğü için hangisi doğrudur?', 'Küçük harfle başlar, çünkü cümle devam etmektedir.', ['Büyük harfle başlar, çünkü yeni cümledir.', 'Büyük harflerle yazılır.', 'Tırnak içine alınır ve tırnaktan ayrılmaz.'], 'Aktarma cümlesi, tırnak içindeki cümleden sonra küçük harfle sürer.'),
  ('Ali, "Yarın gelecek misin?" diye sordu. cümlesinde soru işareti neden tırnak içinde yer alır?', 'Soru, tırnak içindeki söze ait olduğu için', ['Soru işareti tırnaktan önce gelmeli, çünkü cümle soru', 'Soru işareti hiç gereksiz, çünkü cümle bildirme', 'Soru işareti iki kez yazılmalı'], 'Soru işareti, soru olan doğrudan aktarılan sözün parçasıdır; tırnağın içinde kalır.'),
  ('Bir kişiden alıntı yapılırken alıntının kaynağı genellikle hangi işaretle verilir?', 'Yay ayraç içinde', ['Köşeli ayraç içinde', 'Üç nokta ile', 'Eğik çizgi ile'], 'Alıntı sözün sahibi ya da kaynağı yay ayraç içinde yazılabilir.'),
  ('\'Ali, "Çıkın!" diye bağırdı.\' cümlesinde \'diye\'nin küçük harfle başlamasının nedeni nedir?', 'Cümle tırnaktan sonra devam eder.', ['Ünlem işareti cümleyi bitirir.', '\'Diye\' bir özel addır.', 'Tırnak içi cümle yeni paragraf başlatır.'], 'Tırnak içindeki ünlemli söz cümleyi bitirmez; aktarma kısmı küçük harfle devam eder.'),
  ('\'Ayşe\' sözcüğü satır sonunda hangi biçimde bölünebilir?', 'Ay-şe', ['A-yşe', 'Ayş-e', 'A-ysş-e'], '\'Ayşe\' sözcüğü \'ay-şe\' biçiminde hecelenir; tek harf satır sonunda bırakılmaz.'),
  ('Zaman ve yer bildiren sözcüklere gelen \'-ki\' ekinin yanlış yazıldığı cümle hangisidir?', 'Bugünki gazeteyi okudun mu?', ['Evdeki saat bozulmuş.', 'Masadaki kitap benimdir.', 'Dünkü yemek çok lezzetliydi.'], '\'Bugünkü\' sözcüğünde \'ki\' eki \'kü\' biçimindedir; \'bugünki\' hatalıdır.'),
  ('Şapkanın gerektiği ama kullanılmadığı sözcüğün geçtiği cümleyi bulunuz.', 'Kağıtları masaya koyduk.', ['Bu rüzgâr çok sert esiyor.', 'Dükkânı erkenden kapattı.', 'Hâlâ uyuyor musun?'], 'TDK yazımı \'kâğıt\'tır; \'k\' ünsüzünden sonra gelen \'a\' şapkayla gösterilir.'),
  ('Belgisiz zamirlerden birinin bitişik yazılması gerekirken ayrı yazıldığı cümle hangisidir?', 'Hiç birimiz bu sonucu beklemiyorduk.', ['Hiçbir şey söylemedi.', 'Bazı insanlar erken kalkar.', 'Birbirimizi çok severiz.'], '\'Hiçbirimiz\' tek sözcük olarak bitişik yazılır.'),
  ('Bağlaç olan \'ki\'nin hatalı yazıldığı cümleyi bulunuz.', 'Ne yazıkki sınava yetişemedik.', ['Oysaki o kadar kolay değildi.', 'Sanki hiç gitmemiş gibiydi.', 'Çünkü çok yorgundu.'], '\'Ne yazık ki\' ayrı yazılır; \'ki\' bağlaçtır.'),
  ('\'-imiş\' ek fiilinin kurala aykırı yazıldığı cümle aşağıdakilerden hangisidir?', 'Dün akşam evde değil ymişim.', ['Hastaymış, bu yüzden gelemedi.', 'Evdeydik, kimse kapıyı çalmadı.', 'Okuldaydı ama dersi kaçırdı.'], 'Ek fiil sözcüğe bitişik yazılır; \'değilmişim\' ya da \'evde değilmişim\' gibi bitişik biçim gerekir.'),
  ('Dil adının büyük harfle başlamadığı cümleyi bulunuz.', 'Kardeşim fransızca öğreniyor.', ['Annem Almanca öğretmeniydi.', 'Türkçe sözlükte buldum.', 'Bu kitap İngilizceden çevrildi.'], 'Dil adları özel ad kabul edilir; büyük harfle başlar.'),
  ('\'Kitabı\' sözcüğüne bir ek getirilirken hata yapılan cümleyi bulunuz.', 'Kitabı ağaç\'ta okudum.', ['Kitabı ağaçta okudum.', 'Kitabı Ali\'yle okudum.', 'Kitabı evde okudum.'], '\'Ağaç\' genel addır; kesme işareti kullanılmaz: \'ağaçta\'.'),
  ('Kısaltmanın hatalı yazıldığı cümleyi bulunuz.', 'Torbada 3 kg. şeker var.', ['Dr. Ayşe nöbetteydi.', 'TDK yeni sözlüğü yayımladı.', 'Sınıfa 30 m ip lazım.'], '\'kg\' birim simgesidir ve nokta almaz.'),
  ('Ses olayı içermeyen bir bileşik fiilin bitişik yazılarak bozulduğu cümleyi seçiniz.', 'Teklifi kabuletti ve imzaladı.', ['Teklifi reddetti ve gitti.', 'Hataları affetti.', 'Çok sabretti ama sonuç alamadı.'], '\'Kabul etmek\' ayrı yazılır.'),
  ('Hangi cümlede sert ünsüz benzeşmesi yazıma doğru yansıtılmamıştır?', 'Kitap\'da yazan bilgiyi okudum.', ['Kitapta yazan bilgiyi okudum.', 'Sokakta yürürken şarkı söyledi.', 'Ağaçta bir kuş yuvası var.'], '\'Kitap\' genel addır; kesmesiz ve sert ünsüz benzeşmesiyle \'kitapta\' yazılır.'),
  ('\'Sabahleyin\' sözcüğüyle ilgili hangi yazım hatalıdır?', 'sabah leyin', ['sabahleyin', 'akşamleyin', 'öğleyin'], '\'-leyin\' eki sözcüğe bitişik yazılır: \'sabahleyin\'.'),
  ('Hangi cümlede \'hiç kimse\' ifadesi hatalı yazılmıştır?', 'Hiçkimse bana yardım etmedi.', ['Hiç kimse gelmedi.', 'Hiçbir kimse gelmedi.', 'Hiç kimseyi görmedim.'], '\'Hiç kimse\' ayrı yazılır.'),
  ('Aşağıdakilerden hangisinde noktalı virgül özne ile yüklemi ayıracak biçimde yanlış kullanılmıştır?', 'Çocuklar; bahçede oynuyor.', ['Hava soğuk; yine de dışarı çıktık.', 'Kitabı bitirdim; çok beğendim.', 'Yağmur durdu; yola koyulduk.'], 'Noktalı virgül özne ile yüklemi ayırmak için kullanılmaz.'),
  ('Saatin yanlış yazıldığı cümleyi bulunuz.', 'Toplantı saat 14,30\'da başlayacak.', ['Toplantı saat 14.30\'da başlayacak, hazır olun.', 'Toplantı saat 9.00\'da başlayacak.', 'Toplantı saat 17.45\'te başlayacak.'], 'TDK\'ye göre saat ile dakika arasına nokta konur.'),
  ('Ara sözün noktalama bakımından hatalı yazıldığı cümleyi bulunuz.', 'Bu konu bence, tartışmaya değmez.', ['Bu konu, bence, tartışmaya değmez.', 'Ali, benim arkadaşım, bugün geliyor.', 'Yarın, galiba, yağmur yağacak.'], 'Ara söz her iki yanından virgülle ayrılır; yalnız bir yanında virgül bırakmak yanlıştır.'),
  ('Aşağıdaki cümlelerin hangisinde \'ve\' bağlacından önce gereksiz virgül konmuştur?', 'Kitap, defter, ve silgi aldım.', ['Kitap, defter ve silgi aldım bugün.', 'Ali ve Veli geldi.', 'Çay ya da kahve alırım.'], 'Bağlaç \'ve\' ile bağlanan son öğeden önce virgül konmaz.'),
  ('Karşıtlık bağlacından önce virgül eksik bırakılan cümleyi bulunuz.', 'Çok çalıştı ama başarılı olamadı.', ['Çok çalıştı, ama başarılı olamadı.', 'Hava soğuktu, fakat dışarı çıktık.', 'Gelmek istedi, lakin yetişemedi.'], '\'Ama, fakat, lakin\' bağlaçlarından önce virgül konur.'),
  ('Konuşma çizgisinin yanlış kullanıldığı diyaloğu bulunuz.', '— Nereye gidiyorsun diye sordu.', ['— Nereye gidiyorsun? diye sordu.', '— Okula, dedi Ali.', '— Dün nerede idin? diye sordu.'], 'Konuşma çizgisinden sonra gelen söz büyük harfle başlar.'),
  ('Eğik çizginin yanlış kullanıldığı gösterimi bulunuz.', 'Ali/ okula gitti.', ['Öğrenci/öğretmen girişi', '2023/2024 eğitim yılı', 'Kızılay/Ankara'], 'Eğik çizgi iki öğe arasında ve genelde boşluksuz kullanılır; cümle içinde tek başına konmaz.'),
  ('Tırnak içinde noktanın yanlış konduğu cümleyi bulunuz.', 'Ali "Geliyorum". dedi.', ['Ali "Geliyorum." dedi.', 'Ali "Geliyor musun?" diye sordu.', 'Ali "Çık!" diye bağırdı.'], 'Tırnak içindeki cümlenin noktası kapanış tırnağından önce gelir.'),
  ('Aşağıdaki cümlelerden hangisinde yer ve tarih arasındaki noktalama hatalıdır?', 'Ankara. 12 Mayıs 2020', ['Ankara, 12 Mayıs 2020 Salı', 'İstanbul, 3 Ocak 2018', 'İzmir, 25 Aralık 2019'], 'Yer ile tarih arasına virgül konur.'),
  ('Hangi cümlede bağlaç olan \'ki\' öncesinde gereksiz biçimde nokta kullanılmıştır?', 'O kadar yorgundu. ki hemen uyudu.', ['O kadar yorgundu ki hemen uyuyakaldı.', 'Duydum ki sınav ertelenmiş.', 'Öyle sevindi ki ağlayacaktı.'], '\'Ki\' bağlacı cümleyi önceki cümleye bağlar; aralarına nokta konmaz.'),
  ('Aşağıdaki cümlelerin hangisinde iki nokta, sıralamadan önce doğru yerde kullanılmıştır?', 'Dört mevsim vardır: ilkbahar, yaz, sonbahar, kış.', ['Dört mevsim: vardır ilkbahar, yaz, sonbahar, kış.', 'Dört mevsim vardır ilkbahar: yaz, sonbahar, kış.', 'Dört: mevsim vardır ilkbahar, yaz, sonbahar, kış.'], 'Cümle tamamlanıp sıralanacak öğelerden önce iki nokta konur.'),
  ('\'Çocuk ağaç\'ta oynarken düştü.\' cümlesinde hangi düzeltme yapılmalıdır?', '\'ağaç\'ta\' sözcüğündeki kesme işareti kaldırılmalıdır.', ['\'Çocuk\' sözcüğü cümle başında olsa da küçük harfle başlamalıdır.', '\'oynarken\' sözcüğündeki \'-ken\' eki ayrı yazılmalıdır.', 'Cümlenin sonuna ünlem konmalıdır.'], '\'Ağaç\' genel addır; ek kesmeyle ayrılmaz: \'ağaçta\'.'),
  ('\'Ankaralı Mehmet bey bugün geldi.\' cümlesinde büyük harf bakımından hangi düzeltme gerekir?', '\'bey\' yerine \'Bey\' yazılmalıdır.', ['\'Ankaralı\' sözcüğü küçük yazılmalıdır.', '\'bugün\' sözcüğü büyük yazılmalıdır.', '\'geldi\' sözcüğü büyük yazılmalıdır.'], 'Kişi adından sonra gelen \'Bey\' unvanı büyük harfle yazılır.'),
  ('\'Dr. Ahmet 14:30\'da hastaları kabul edecek.\' cümlesinde saat yazımı nasıl düzeltilmelidir?', '\'14:30\'da\' yerine \'14.30\'da\' yazılarak', ['\'Dr.\' yerine bütün harfleri büyük \'DR\' yazılarak', '\'Ahmet\' sözcüğü küçük harfle başlatılarak', '\'hastaları\' ayrı yazılarak'], 'TDK saat ve dakikayı nokta ile ayırır.'),
  ('\'Sınav 5 Haziran\'da yapılıcak.\' cümlesinde yazım hatası hangisidir?', '\'yapılıcak\' yerine \'yapılacak\' yazılmalıdır.', ['\'Haziran\'da\' sözcüğü ay adı olduğu için büyük harfle başlamamalıdır.', '\'Sınav\' sözcüğü cümle başında olsa da küçük yazılmalıdır.', '\'5\' rakamla yazılmamalıdır.'], 'Gelecek zaman eki \'-acak/-ecek\' biçimindedir: \'yapılacak\'.'),
  ('\'Bu kitaptan hiç birini okumadım.\' cümlesinin yazım hatası nasıl düzeltilir?', '\'hiç birini\' ifadesi bitişik, tek sözcük olarak yazılarak', ['\'okumadım\' sözcüğündeki olumsuzluk eki ayrı yazılarak', '\'kitaptan\' sözcüğü kitap ve ek biçiminde ayrı yazılarak', '\'Bu\' küçük yazılarak'], '\'Hiçbiri\' tek sözcüktür; çekim ekleri ona bitişir: \'hiçbirini\'.'),
  ('\'Ali ve Veli, geldi\' cümlesinde virgül hatası nasıl giderilir?', 'Virgül kaldırılıp cümlenin sonuna nokta konur.', ['Virgülden sonra \'ama\' bağlacı eklenerek cümle sürdürülür.', 'Virgül noktalı virgülle değiştirilerek korunur.', 'Virgül iki noktaya dönüştürülür.'], 'Özne ile yüklem arasına virgül konmaz.'),
  ('\'Ne yazıkki yarışmayı kaybettik.\' cümlesindeki yazım yanlışı nasıl giderilir?', '\'yazıkki\' yerine \'yazık ki\' yazılarak', ['\'yarışmayı\' sözcüğü \'yarışma\' ve ek biçiminde ayrı yazılarak', '\'kaybettik\' sözcüğü \'kayıp ettik\' biçiminde ayrı yazılarak', '\'Ne\' küçük harfle yazılarak'], 'Bağlaç \'ki\' ayrı yazılır.'),
  ('\'Her şeyi biliyorsun ama birşey söylemiyorsun.\' cümlesindeki yazım yanlışı nasıl düzeltilir?', '\'birşey\' yerine \'bir şey\' yazılarak', ['\'Her şeyi\' yerine \'Herşeyi\' yazılarak', '\'biliyorsun\' ayrı yazılarak', '\'söylemiyorsun\' bitişik bırakılarak'], '\'Bir şey\' ayrı yazılır.'),
  ('\'Yarın Ali\'yle buluşucam.\' cümlesinde yazı dili bakımından hangi düzeltme gerekir?', '\'buluşucam\' yerine \'buluşacağım\' yazılmalıdır.', ['\'Yarın\' yerine cümle başında \'yarın\' yazılmalıdır.', '\'Ali\'yle\' özel ad olsa da kesmesiz yazılmalıdır.', '\'buluşucam\' ayrı yazılmalıdır.'], 'Yazım dilinde konuşma ağzı kullanılmaz; gelecek zaman \'-acağım\' biçimindedir.'),
  ('Aşağıdaki boşluklu cümlelerden hangisinde \'de/da\' bitişik yazılmalıdır?', 'Bu odan___ kimse kalmadı.', ['Dün ___ sana uğramıştım, hatırlıyor musun.', 'Ali ___ Veli de geldi.', 'Bunu sen ___ biliyorsun ama söylemiyorsun.'], '\'Odanda\' sözcüğünde bulunma eki vardır; bu yüzden bitişik yazılır. Diğerlerinde bağlaç \'de\' ayrı yazılır.'),
  ('\'Bende senin kalemin var.\' cümlesinde \'bende\' sözcüğü neden bitişik yazılır?', '\'Ben\' zamirine yer-durum bildiren hâl eki eklenmiştir.', ['\'De\' burada bağlaç olduğu için bitişik yazılması gerekir.', 'Ünlü uyumu gereği ek bitişik yazılmak zorundadır, başka yol yoktur.', '\'Bende\' tek heceli sözcük olduğu için bitişik yazılır, bağlaç değildir.'], '\'Bende\' sözcüğünde \'ben + -de\' bulunma ekidir; ek bitişik yazılır.'),
  ('Aşağıdaki cümlelerin hangisinde bulunma eki ile bağlaç \'de\' ikisi birlikte doğru yazılmıştır?', 'Ali evde kalmış, Ayşe de okula gitmiş.', ['Ali ev de kalmış, Ayşe de okula gitmiş.', 'Ali evde kalmış, Ayşede okula gitmiş.', 'Ali ev de kalmış, Ayşe okulda gitmiş.'], '\'Evde\' bulunma eki olarak bitişik, \'Ayşe de\' bağlaç olarak ayrı yazılır.'),
  ('\'Kitaplar masada duruyor, defterler de çantada.\' cümlesinde ilk \'da\' ek, ikinci \'de\' bağlaçtır. Buna göre hangisi doğrudur?', 'İlk ek bitişik, ikinci bağlaç ayrı yazılmıştır.', ['İkisi de aynı görevde olduğu için ayrı yazılır ve doğrudur.', 'Birincisi ayrı, ikincisi bitişik yazılmalıdır, çünkü görevleri ters.', 'İkisi de bitişik yazılmalıdır, çünkü ikisi de ektir.'], '\'Masada\' bulunma ekidir, \'defterler de\' ise bağlaçtır.'),
  ('\'Çünkü yağmur yağıyordu.\' cümlesinde \'çünkü\' sözcüğünün yazımı neden bitişiktir?', '\'Ki\' kalıplaşarak sözcüğün bir parçası olmuştur.', ['\'Ki\' burada ilgi eki olduğu için bitişik yazıldığından', '\'Ki\' burada soru eki olduğu için ve soru ekleri bitişik olduğundan', '\'Çünkü\' bir yabancı sözcük olduğu ve ek almadığı için'], '\'Çünkü, sanki, belki, oysaki\' gibi sözcüklerde \'ki\' kalıplaşmıştır; bitişik yazılır.'),
  ('\'Masadaki kitabı ver.\' ve \'Bil ki sana güveniyorum.\' cümlelerindeki \'ki\' sözcüklerinin farkı nedir?', 'İlki ilgi eki olarak bitişik, ikincisi bağlaç olarak ayrı yazılır.', ['İkisi de bağlaçtır; ikisi de ayrı yazılmalıdır.', 'İkisi de ektir; ikisi de bitişik yazılmalıdır.', 'İlki bağlaç, ikincisi ektir; ilki ayrı, ikincisi bitişiktir.'], '\'Masadaki\' sözcüğündeki \'ki\' aitlik eki; \'bil ki\' içindeki \'ki\' ise bağlaçtır.'),
  ('\'Yarın gelirsen sana göstereyim ki ne yaptığımı anlayasın.\' cümlesinde \'ki\'nin görevi nedir?', 'Cümleyi önceki cümleye bağlayan bağlaç', ['İlgi eki olarak kullanılan bitişik yazılan ek', 'Soru eki', 'Zaman eki'], 'Amaç ya da sonuç bildiren cümleleri bağlayan \'ki\' ayrı yazılan bir bağlaçtır.'),
  ('\'Annesi gelmiş mi?\' sorusunda soru ekinin sözcükten ayrı yazılması gereken kuralı hangisidir?', 'Soru eki hiçbir zaman önceki sözcüğe bitişmez.', ['Soru eki yalnız fiilden sonra ayrı yazılır.', 'Soru eki yalnız isimlerden sonra bitişik yazılır.', 'Soru eki büyük harfle başlar.'], 'Soru eki (\'mı, mi, mu, mü\') önceki sözcükten ayrı yazılır.'),
  ('\'Gelecek ___ diye sordu.\' boşluğa soru eki gelecek şekilde \'gelecek + mi\' + \'diye\' birleşimi nasıl yazılır?', 'Gelecek mi diye sordu.', ['Gelecekmi diye sordu.', 'Gelecek mı diye sordu.', 'Gelecek - mi diye sordu.'], '\'Gelecek\' son ünlüsü \'e\' olduğundan \'mi\' gelir ve ayrı yazılır.'),
  ('\'Ali okula gitti, ben ise evde kaldım.\' cümlesindeki \'ise\' için hangisi doğrudur?', 'Karşılaştırma bağlacıdır; ayrı yazılır.', ['Ek fiildir; mutlaka bitişik yazılır.', 'Soru ekidir; soru anlamı katar, ayrı yazılır.', 'Pekiştirme ekidir; sözcüğe bitişik yazılır.'], 'Zıtlık kuran \'ise\' ayrı yazılan bir bağlaçtır; şart eki ise \'-sa\'dır.'),
  ('\'Hava çok sıcaktı ___ camı açtım.\' cümlesinde bağlaç mı ek fiil mi gerekir? Doğru yazım hangisidir?', 'Hava çok sıcaktı, bu yüzden camı açtım.', ['Hava çok sıcaktıbu yüzden camı açtım.', 'Hava çok sıcak dı bu yüzden camı açtım.', 'Hava çok sıcaktı buyüzden camı açtım.'], '\'Sıcaktı\' ek fiil bitişik, \'bu yüzden\' ayrı yazılır.'),
  ('\'Sen de gittin, ben de.\' cümlesindeki ikinci \'de\' neden cümlenin sonunda yalın kalmıştır?', 'Yüklemi eksiltilmiş bağlaçtır; ayrı yazılır.', ['Yüklemi olan bir ektir; sözcüğe bitişik yazılır.', 'Soru ekidir; soru anlamı katar ve ayrı yazılır.', 'Kısaltmadır; harfler arasına nokta konur.'], 'Eksiltili cümlede \'ben de\' bağlaç olarak ayrı yazılır.'),
  ('Aşağıdaki sözcüklerden hangisinde \'ki\' sözcüğün bir parçası olarak bitişik yazılmaz?', 'madem ki', ['belki', 'sanki', 'çünkü'], '\'Madem ki\' ayrı yazılır; diğerleri kalıplaşmış, bitişik sözcüklerdir.'),
  ('Türk Dil Kurumu, Atatürk\'ün önderliğinde hangi yılda \'Türk Dili Tetkik Cemiyeti\' adıyla kurulmuştur?', '1932', ['1928', '1924', '1938'], 'Kurum 12 Temmuz 1932\'de kurulmuştur.'),
  ('Türk alfabesinin harf sayısı ve ünlü-ünsüz dağılımı hangi seçenekte doğru verilmiştir?', '29 harf: 8 ünlü, 21 ünsüz', ['28 harf: 8 ünlü, 20 ünsüz', '29 harf: 9 ünlü, 20 ünsüz', '30 harf: 8 ünlü, 22 ünsüz'], 'Türk alfabesi 29 harften oluşur; sekiz harf ünlü, yirmi bir harf ünsüzdür.'),
  ('Yabancı kökenli \'chauffeur\' sözcüğünün Türkçeye uyarlanmış biçimi TDK ilkesine göre nasıl yazılır?', 'Okunuşuna uygun biçimde yazılır.', ['Özgün yazımıyla yazılır.', 'Latince karşılığıyla yazılır.', 'Sesleri hiç değiştirilmeden yazılır.'], 'Yabancı sözcükler Türkçeye geçerken Türkçenin söyleyişine göre yazılır: \'şoför\'.'),
  ('\'Kitap\' sözcüğü \'-ı\' ekini alınca yazımda ne olur?', 'Sondaki \'p\' yumuşar: \'kitabı\'', ['Sözcük aynı kalır ve ek bitişir: \'kitapı\'', 'Sondaki \'p\' düşer ve ünlü kalır: \'kitaı\'', 'Araya kesme işareti girer: \'kitap\'ı\' biçiminde'], 'Çok heceli sözcüklerin sonundaki \'p, ç, t, k\' ünsüzleri ünlü ile başlayan ek gelince yumuşar; yazıya da yansıtılır.'),
  ('\'Sayın Bakan\', \'Dr. Ali Bey\', \'Prof. Dr. Ayşe Hanım\' ifadelerinin ortak noktası nedir?', 'Unvanlar özel adla birlikte kullanıldığında büyük harfle yazılır.', ['Üçünde de unvanlar küçük harfle yazılır, çünkü sıfattır.', 'Üçünde de noktalama işareti gereksizdir ve konmaz.', 'Üçünde de sözcükler bitişik yazılır, çünkü kalıplaşmıştır.'], 'Özel adın parçası olan unvanlar büyük harfle başlar.'),
  ('Aşağıdaki cümlelerden hangisi yazım ve noktalama bakımından tamamen doğrudur?', 'Herkes yarın saat 14.30\'da toplanacak.', ['Herkez yarın saat 14.30\'da toplanacak.', 'Herkes yarın saat 14.30 da toplanacak, unutmayın.', 'Herkes yarın saat 14,30\'da toplanacak olursa.'], 'Birinci seçenek tüm kurallara uygundur; diğerlerinde sırasıyla \'herkez\', ayrı yazılmış ek ve virgül hatası vardır.'),
  ('Belirsizlik bildiren sözcüklerin ve özel ad ekinin birlikte denetlendiği hangi cümle tamamen doğrudur?', 'Hiçbir şey yapmadan Ali\'nin gelmesini bekledik.', ['Hiç bir şey yapmadan Ali\'nin gelmesini bekledik.', 'Hiçbir şey yapmadan Alinin gelmesini bekledik.', 'Hiçbirşey yapmadan Ali\'nin gelmesini bekledik.'], 'Birinci seçenek doğrudur: \'hiçbir\' bitişik, \'şey\' ayrı ve özel ad kesmeyle ayrılmıştır.'),
  ('Aşağıdaki cümlelerden hangisinde yazım yanlışı yoktur?', 'Sen de bu akşam bizimle yemeğe gelir misin?', ['Sende bu akşam bizimle yemeğe gelir misin?', 'Sen de bu akşam bizimle yemeğe gelirmisin?', 'Sen de bu akşam bizimle yemeğe gelir mi sin?'], 'Bağlaç \'de\' ve soru eki \'mi\' doğru yazılmıştır: \'sen de\', \'gelir misin\'.'),
  ('Aşağıdaki cümlelerden hangisi büyük harf ve kesme işareti bakımından doğrudur?', 'Karadeniz\'in kıyısındaki Rize\'de çay yetiştirilir.', ['karadeniz kıyısındaki rizede çay yetiştirilir.', 'Karadeniz\'in kıyısındaki Rize de çay yetiştirilir ve satılır.', 'Karadenizin kıyısındaki Rizede çay yetiştirilir.'], 'Özel adlar büyük harfle başlar ve çekim ekleri kesmeyle ayrılır.'),
  ('Aşağıdaki cümlelerden hangisinde bileşik sözcük ve ekler doğru yazılmıştır?', 'Akciğer hastalıklarına karşı sabahleyin yürüyüş yapıyor.', ['Ak ciğer hastalıklarına karşı sabah leyin yürüyüş yapıyor.', 'Akciğer hastalıklarına karşı sabah leyin yürüyüş yapıyor.', 'Ak ciğer hastalıklarına karşı sabahleyin yürüyüş yapıyor.'], '\'Akciğer\' ve \'sabahleyin\' bitişik yazılır.'),
  ('\'Hergün yada ikigünde bir kütüphaneye gidiyorum.\' cümlesinde kaç yazım yanlışı vardır?', 'üç', ['iki', 'dört', 'beş'], '\'Her gün\' ayrı, \'ya da\' ayrı, \'iki günde\' ayrı yazılmalıdır; üç hata vardır.'),
  ('\'Herkez birşey söyledi ama hiçbirimiz anlamadık.\' cümlesinde kaç yazım yanlışı vardır?', 'iki', ['bir', 'üç', 'dört'], '\'Herkes\' ve \'bir şey\' hatalıdır; \'hiçbirimiz\' doğrudur.'),
  ('\'Sabahleyin kalkıp yanlız başına kağıt toplamaya gitti.\' cümlesinde kaç yazım yanlışı vardır?', 'iki', ['bir', 'üç', 'dört'], '\'Yalnız\' ve \'kâğıt\' yanlış yazılmıştır; \'sabahleyin\' doğrudur.'),
  ('\'Hava çok güzeldi, hemde rüzgar yoktu.\' cümlesinde kaç yazım yanlışı vardır?', 'iki', ['bir', 'üç', 'dört'], '\'Hem de\' ayrı ve \'rüzgâr\' şapkalı yazılmalıdır.'),
  ('\'Ayşe\'ye mektup yazdım, o da bana cevap verdi, fakat Ahmetten haber alamadım.\' cümlesinde kaç yazım yanlışı vardır?', 'bir', ['iki', 'üç', 'dört'], 'Yalnız \'Ahmet\'ten\' kesmeyle yazılmalıdır.'),
  ('\'Dr. Ali bey hastaları 14:30\'da kabul ediyor.\' cümlesinde kaç yazım ve noktalama yanlışı vardır?', 'iki', ['bir', 'üç', 'dört'], '\'Bey\' büyük harfle ve saat \'14.30\'da\' biçiminde yazılmalıdır.'),
  ('\'Kitap ta defter de masanın üstündeydi, çantamda da bir şey yoktu.\' cümlesinde kaç yazım yanlışı vardır?', 'bir', ['iki', 'üç', 'dört'], 'Yalnız \'kitap da\' bağlacı ayrı ve \'da\' biçiminde yazılmalıdır.'),
  ('Aşağıdaki cümlelerden hangisinde deniz adı doğru yazılmıştır?', 'Ege Denizi\'nin kıyılarında tatil yaptık.', ['Ege Denizinin uzun kıyılarında tatil yaptık.', 'Ege Deniz\'inin kıyılarında tatil yaptık.', 'ege denizi kıyılarında tatil yaptık.'], 'Deniz adları çok sözcüklüyse her sözcük büyük başlar ve ek kesmeyle ayrılır: \'Ege Denizi\'nin\'.'),
  ('Dört cümleden hangisinde belirli bir bulvarın adı ve eki hatasız yazılmıştır?', 'Atatürk Bulvarı\'ndan geçerek okula vardık.', ['atatürk bulvarı üzerinden geçerek okula vardık.', 'Atatürk bulvarından geçerek okula vardık.', 'Atatürk Bulvarından geçerek okula vardık'], 'Belirli yer adlarında her sözcük büyük başlar; ek kesmeyle ayrılır.'),
  ('\'Bu şehirde üç tane üniversite var.\' ile \'Ankara Üniversitesi bu şehirdedir.\' cümlelerindeki üniversite sözcüğü için hangisi doğrudur?', 'Genel kullanımda küçük, belirli kurum adında büyük harfle başlar.', ['İkisinde de küçük harfle başlar, çünkü genel addır.', 'İkisinde de büyük harfle başlar, çünkü kurumdur.', 'Yalnız ikinci cümlede küçük yazılır, ilkinde büyüktür.'], 'Özel ad olarak kurum adının parçası olan sözcük büyük, genel kullanımda küçük yazılır.'),
  ('Hangi cümlede büyük harfle başlaması gereken bir hayvan adı küçük yazılmıştır?', 'Komşunun köpeği karabaş çok akıllıdır.', ['Bahçedeki kedi akşam yemeğini bekliyor.', 'Atımız Rüzgâr sabah koşuya çıktı.', 'Dün kuşlar erkenden göç etti.'], 'Hayvanlara verilen özel adlar büyük harfle başlar.'),
  ('Hangi cümlede bir romanın adı büyük harfle başlaması gerekirken küçük harfle yazılmıştır?', 'Orhan Pamuk\'un kar romanını okudum.', ['Dün akşam yeni bir roman okudum.', 'Yaşar Kemal\'in İnce Memed romanı çok ünlüdür.', 'Reşat Nuri\'nin Çalıkuşu romanını sevdim.'], 'Kitap adları özel addır; yazar adı da büyük başlar.'),
  ('\'Yüzde beşlik\' anlamında \'%5\' sayısına \'-lik\' eki gelirse doğru yazım hangisidir?', '%5\'lik', ['%5lik', '% 5 lik', '%5-lik'], 'Rakamlara gelen ekler kesme işaretiyle ayrılır.'),
  ('\'Üç\' sayısının sıra sayısı olarak rakamla ve ekle yazımı hangisidir?', '3\'üncü', ['3üncü', '3 üncü', '3 - üncü'], 'Rakamla yazılan sayıya gelen ek kesmeyle ayrılır; ünlü uyumu \'üncü\' biçimini gerektirir.'),
  ('\'Ayşe Hanım\'a mektup yazdık.\' cümlesindeki kesme işareti için hangisi doğrudur?', 'Özel ad öbeğine gelen ek kesmeyle ayrılır.', ['Kesme işareti gereksizdir, ek bitişik yazılır.', 'Kesme sözcüğün önüne gelmelidir, ekten sonra değil.', 'Kesme yerine kısa çizgi konmalıdır.'], 'Ek, özel ad öbeğinin sonundaki sözcüğe kesmeyle bağlanır: \'Ayşe Hanım\'a\'.'),
  ('\'Çankırı\'ya\', \'Rize\'ye\' ve \'Bolu\'ya\' sözcüklerinde \'y\' harfinin görevi nedir?', 'Kaynaştırma ünsüzü olarak ünlüler arasına girer.', ['Çoğul ekidir ve ünlü uyumuna girer.', 'Soru ekidir ve sözcüğe bitişir.', 'Yapım ekidir ve yeni sözcük türetir.'], 'Ünlüyle biten sözcüklere ünlü ile başlayan ek gelince araya \'y\' kaynaştırması girer; kesme işareti özel adla ek arasına konur.'),
  ('Atatürk adından türeyen aşağıdaki biçimlerden hangisi kesme işareti almaz?', 'Atatürkçülük', ['Atatürk\'e doğru', 'Atatürk\'ün kitabı', 'Atatürk\'ten sonra'], '\'-çülük\' yapım ekidir; türeyen sözcük kesmesiz yazılır.'),
  ('\'Konyalı bir arkadaşımla Konya\'ya gittik.\' cümlesinde birinci ve ikinci sözcük için hangisi doğrudur?', '\'Konyalı\' kesmesiz, \'Konya\'ya\' kesmeli yazılır.', ['İkisi de kesmeli yazılır: \'Konya\'lı\' ve \'Konya\'ya\'.', 'İkisi de kesmesiz yazılır: \'Konyalı\' ve \'Konyaya\'.', '\'Konyalı\' kesmeli, \'Konya\'ya\' kesmesiz yazılır; bu bir kuraldır.'], 'Yapım eki alan sözcükte kesme kullanılmaz; çekim eki alan özel adda kullanılır.'),
  ('Rakamla \'25.\' diye gösterilen sıra sayısının sözcükle doğru yazımı hangisidir?', 'yirmi beşinci', ['yirmibeşinci', 'yirmi-beşinci', 'yirmi beş inci'], 'Sıra sayıları da sayı sözcükleri gibi ayrı yazılır; son sayıya \'-inci\' eki bitişir.'),
  ('\'Dört dörtlük\' ve \'yüzde yüz\' ifadelerinin yazımı için hangisi doğrudur?', 'İkisi de ayrı yazılan sözcük gruplarıdır.', ['İkisi de bitişik yazılır.', 'İkisi de kısa çizgiyle yazılır.', 'Yalnız \'yüzde yüz\' bitişik yazılır.'], 'Bu ifadeler iki ayrı sözcükten oluşur ve ayrı yazılır.'),
  ('\'Bir iki gün sonra gelirim.\' cümlesindeki \'bir iki\' için hangisi doğrudur?', 'Yaklaşık sayı anlatan ayrı yazılan sözcük grubudur.', ['\'Biriki\' olarak bitişik yazılır.', '\'Bir-iki\' olarak kısa çizgiyle yazılır.', '\'Bir iki\' bir ikilemedir ve nokta alır.'], '\'Bir iki\' yaklaşık miktar bildirir; ayrı yazılır.'),
  ('\'İkide bir\' ifadesinin yazımı için hangisi doğrudur?', 'Ayrı yazılır: \'ikide bir\'.', ['Bitişik yazılır: \'ikidebir\'.', 'Kısa çizgiyle yazılır: \'ikide-bir\'.', 'Tırnak içinde yazılır.'], '\'İkide bir\' sık sık anlamında ayrı yazılan bir kalıptır.'),
  ('\'Üçte iki\', \'beşte bir\' gibi kesir adlarının sözcükle yazımı için hangisi doğrudur?', 'Sayılar ayrı yazılır; ek, ilk sayıya bitişir.', ['Tümü bitişik yazılır.', 'Ek sayıdan ayrı yazılır.', 'Aralarına kısa çizgi konur.'], 'Kesir ifadelerinde \'üçte iki\' biçiminde ek ilk sayıya bitişir.'),
  ('\'XX. yüzyıl\' gösterimindeki Roma rakamı ve nokta için hangisi doğrudur?', 'Roma rakamı sıra sayısı belirtir ve nokta konur.', ['Roma rakamı hiçbir zaman nokta almaz.', 'Roma rakamları yalnız kitap adlarında kullanılır.', 'Roma rakamı yalnız yılları gösterir.'], 'Roma rakamlarıyla yazılan sıra sayılarından sonra da nokta konur.'),
  ('\'Hemen hemen\' ifadesinin yazımı için hangisi doğrudur?', 'Ayrı yazılır.', ['Bitişik yazılır: \'hemenhemen\'.', 'Kısa çizgiyle yazılır: \'hemen-hemen\'.', 'Yalnız cümle başında ayrı yazılır.'], 'Tekrarlı zarf grubu ayrı yazılır.'),
  ('\'Ara sıra\' ve \'arada sırada\' ifadeleri için hangisi doğrudur?', 'İkisi de ayrı yazılır.', ['İkisi de bitişik yazılır.', 'Yalnız \'ara sıra\' bitişik yazılır.', 'Yalnız \'arada sırada\' bitişik yazılır.'], 'Bu ikilemeler ayrı yazılır.'),
  ('\'Aynı zamanda\' ve \'şu anda\' ifadeleri için hangisi doğrudur?', 'Sözcükleri ayrı yazılır.', ['Sözcükleri bitişik yazılır.', 'Yalnız \'aynı zamanda\' ayrı yazılır.', 'Yalnız \'şu anda\' ayrı yazılır.'], 'Zaman bildiren bu öbekler ayrı yazılır.'),
  ('\'Her ne kadar\' ve \'yine de\' ifadelerinin yazımı için hangisi doğrudur?', 'İkisi de ayrı yazılır.', ['\'Herne kadar\' bitişik, \'yine de\' ayrı yazılır.', 'İkisi de bitişik yazılır.', 'Yalnız \'yine de\' bitişik yazılır.'], 'Bu ifadeler ayrı sözcüklerden oluşur.'),
  ('\'Gerçi ... ama\' yapısındaki \'gerçi\' sözcüğünün yazımı için hangisi doğrudur?', 'Tek sözcük olarak bitişik yazılır.', ['\'Gerçi\' ayrı yazılır: \'gerçek i\'.', 'Kısa çizgiyle yazılır.', 'Büyük harfle başlar.'], '\'Gerçi\' bağlaç olarak tek sözcüktür.'),
  ('\'Hatta\', \'ayrıca\', \'yalnızca\' sözcüklerinin ortak yazım özelliği nedir?', 'Tek sözcük olarak bitişik yazılırlar.', ['Üçü de ayrı yazılır.', 'Üçü de kısa çizgiyle yazılır.', 'Üçünün ilk harfi büyük yazılır.'], 'Bu bağlaç ve zarflar tek sözcüktür.'),
  ('\'Her biri\' ile \'birçoğu\' sözcüklerinin yazımı için hangisi doğrudur?', '\'Her biri\' ayrı, \'birçoğu\' bitişik yazılır.', ['İkisi de bitişik yazılır.', '\'Her biri\' bitişik, \'birçoğu\' ayrı yazılır.', 'İkisi de ayrı yazılır.'], '\'Her biri\' iki sözcüktür; \'birçoğu\' tek sözcüktür.'),
  ('\'Ne zaman\', \'ne kadar\' ve \'ne gibi\' ifadelerinin yazımı için hangisi doğrudur?', 'Üçü de iki ayrı sözcük olarak yazılır.', ['Üçü de bitişik yazılır.', 'Yalnız \'ne zaman\' ayrı yazılır.', 'Yalnız \'ne gibi\' bitişik yazılır.'], 'Bunlar soru anlamlı sözcük öbekleridir; ayrı yazılır.'),
  ('\'Çalışkan\' sözcüğüne bildirme eki getirildiğinde hangi yazım doğrudur?', 'çalışkandır', ['çalışkantır', 'çalışkan dır', 'çalışkandur'], '\'n\' ünsüzü yumuşak olduğundan ek \'dır\' kalır ve bitişik yazılır; son ünlü \'a\' olduğu için \'ı\' ile yazılır.'),
  ('\'Ağaç\' sözcüğüne bildirme eki \'-dır\' getirilirse doğru yazım hangisidir?', 'ağaçtır', ['ağaçdır', 'ağaç tır', 'ağaçtur'], '\'ç\' sert ünsüz olduğundan ek \'tır\' olur ve bitişik yazılır.'),
  ('\'Göz\' sözcüğüne bildirme eki getirildiğinde ünlü uyumuna göre doğru yazım hangisidir?', 'gözdür', ['gözdır', 'gözdir', 'gözdur'], 'Son ünlü \'ö\' olduğundan ek \'dür\' biçimini alır.'),
  ('\'Yorgun\' sözcüğüne bildirme eki getirildiğinde doğru yazım hangisidir?', 'yorgundur', ['yorgundır', 'yorgunnur', 'yorgun dur'], 'Son ünlü \'u\' olduğundan ek \'dur\' biçimini alır; ek bitişik yazılır.'),
  ('\'Türkiye\' özel adına bildirme eki getirilirse doğru yazım hangisidir?', 'Türkiye\'dir', ['Türkiyedir', 'Türkiye dir', 'Türkiye\'tir'], 'Özel ada gelen ek kesmeyle ayrılır; son ses ünlü olduğundan \'dir\' biçimi kalır.'),
  ('\'Soğuk\' sözcüğü ve \'idi\' ek fiili birleşince hangi yazım doğrudur?', 'soğuktu', ['soğukdu', 'soğuk tu', 'soğukdı'], 'Sert ünsüz \'k\'den sonra ek \'tu\' olur; ünlü uyumuna göre \'u\' ile yazılır.'),
  ('\'Yüzyıl\' sözcüğünün kısaltılmış yazımı hangisidir?', 'yy.', ['yüz.', 'y.y', 'YY'], '\'Yüzyıl\' kısaltması \'yy.\' biçimindedir.'),
  ('\'Ve diğerleri\' anlamındaki kısaltma hangisidir?', 'vd.', ['vb', 'v.d', 'VD'], '\'Ve diğerleri\' sözcük grubu \'vd.\' biçiminde kısaltılır.'),
  ('\'Sayfa\' sözcüğünün kaynakça gösteriminde kısaltılmış biçimi hangisidir?', 's.', ['sf', 'S', 'say.'], 'Sayfa kısaltması \'s.\' biçimindedir; çoğulu \'ss.\' olur.'),
  ('\'Doçent Doktor\' unvanının kısaltılmış yazımı hangisidir?', 'Doç. Dr.', ['Doc Dr', 'DOÇ.DR.', 'Doç.Dr'], 'Her unvan kısaltması nokta alır ve unvanlar arasında boşluk bırakılır.'),
  ('Bir yazıdaki bütün başlıkların noktalama bakımından tutarlı olması ne anlama gelir?', 'Sonlarına nokta konmaması, soru ya da ünlem varsa onun korunması', ['Tümünün sonuna nokta konması', 'Yalnız ilk başlığa soru işareti konması', 'Başlıkların tümünün sonuna iki nokta konması'], 'Başlık sonunda nokta bulunmaz; gerekliyse soru ya da ünlem işareti kullanılır.'),
  ('\'Paket 200 kg. geliyor.\' cümlesinde hangi kural ihlal edilmiştir?', 'Ölçü birimi simgeleri küçük harfle ve noktasız yazılır.', ['Unvan kısaltmaları nokta ile yazılır.', 'Rakamla yazılan sıra sayısından sonra nokta konur.', 'Kısaltmaya gelen ek, kısaltmanın okunuşuna göre getirilir.'], '\'kg\' birim simgesidir ve nokta almaz.'),
  ('\'Kimin geldiğini soruyor?\' cümlesinde hangi kural ihlal edilmiştir?', 'Dolaylı anlatılan soru cümlesi nokta ile biter.', ['Hitap sözünden sonra virgül konur.', 'Tırnak içindeki cümlenin noktası kapanış tırnağından önce gelir.', 'Başlıkların sonuna nokta konmaz.'], 'Dolaylı soru bildirme cümlesi olduğundan nokta ile bitirilmelidir.'),
  ('\'Dün gece çok hasta ymış.\' yazan bir öğrenci hangi kuralı ihlal etmiştir?', 'Ek fiil, bağlandığı sözcüğe bitişik yazılır.', ['Soru eki \'mi\' kendinden önceki sözcükten ayrı yazılır.', 'Bağlaç olan \'de/da\' kendinden önceki sözcükten ayrı yazılır.', 'Bağlaç olan \'ki\' kendinden önceki sözcükten ayrı yazılır.'], 'Ek fiil sözcüğe bitişik yazılır: \'hastaymış\'.'),
  ('\'15 mayıs 2020 Cuma günü toplanacağız.\' cümlesinde hangi yazım kuralı ihlal edilmiştir?', 'Belirli tarihteki ay ve gün adları büyük harfle başlar.', ['Özel adlara getirilen çekim ekleri kesme işaretiyle ayrılır.', 'Unvan kısaltmaları nokta ile yazılır.', 'Rakamla yazılan sıra sayısından sonra nokta konur.'], 'Belirli tarihte ay adı büyük harfle yazılmalıdır: \'15 Mayıs 2020\'.'),
  ('\'Ne yazıkki sınavı kaçırdık.\' cümlesinde hangi kural ihlal edilmiştir?', 'Bağlaç olan \'ki\' kendinden önceki sözcükten ayrı yazılır.', ['Bağlaç olan \'de/da\' kendinden önceki sözcükten ayrı yazılır.', 'Seçenek bağlacı \'ya da\' ayrı yazılır.', 'Ek fiil, bağlandığı sözcüğe bitişik yazılır.'], '\'Ne yazık ki\' ayrı yazılır; \'ki\' bağlaçtır.'),
  ('\'Kitap\'ta bir hata buldum.\' cümlesindeki kesme işareti hangi kuralı ihlal eder?', 'Genel adlara gelen ekler kesme işaretiyle ayrılmaz.', ['Yapım ekleri özel adlardan kesmeyle ayrılmaz.', 'Özel adlara getirilen çekim ekleri kesme işaretiyle ayrılır.', 'Kısaltmaya gelen ek, kısaltmanın okunuşuna göre getirilir.'], '\'Kitap\' genel addır; ek kesmeyle ayrılmaz: \'kitapta\'.'),
  ('Kâğıt yerine \'kağıt\' yazan bir öğrenci hangi kuralı gözden kaçırmıştır?', 'Ünsüzü inceltmek gereken sözcüklerde ünlünün üzerine şapka konur.', ['Kısaltmaya gelen ek, kısaltmanın okunuşuna göre getirilir.', 'Genel adlara gelen ekler kesme işaretiyle ayrılmaz.', 'Belirli tarihteki ay ve gün adları büyük harfle başlar.'], '\'Kâğıt\' sözcüğünde k ünsüzünü inceltmek için şapka kullanılır.'),
  ('\'Elma, armut ve, üzüm aldık.\' cümlesinde hangi noktalama kuralı ihlal edilmiştir?', '\'Ve\' bağlacından hemen önce virgül konmaz.', ['Hitap sözünden sonra virgül konur.', 'Dolaylı anlatılan soru cümlesi nokta ile biter.', 'Tırnak içindeki cümlenin noktası kapanış tırnağından önce gelir.'], '\'Ve\' bağlacından önce virgül konmaz.'),
  ('\'Annem ile gittim.\' ifadesinin \'Annem le gittim.\' biçiminde yazılması hangi kuralı ihlal eder?', '\'İle\' sözcüğü kısaltılınca sözcüğe bitişik yazılır.', ['Bağlaç olan \'de/da\' kendinden önceki sözcükten ayrı yazılır.', 'Soru eki \'mi\' kendinden önceki sözcükten ayrı yazılır.', 'Ek fiil, bağlandığı sözcüğe bitişik yazılır.'], '\'İle\' kısaltılırsa sözcüğe bitişik yazılır: \'annemle\'.'),
  ('\'A C. Yılmaz\' biçiminde bir imza yazan öğrenci hangi kuralı gözden kaçırmıştır?', 'Kişi adlarının kısaltılan harflerinden sonra nokta konur.', ['Unvan kısaltmaları nokta ile yazılır.', 'Ölçü birimi simgeleri küçük harfle ve noktasız yazılır.', 'Rakamla yazılan sıra sayısından sonra nokta konur.'], 'Kişi adı kısaltmalarında her baş harften sonra nokta konur: \'A. C. Yılmaz\'.'),
  ('\'Bir daha\' ve \'bir de\' ifadelerinin yazımıyla ilgili hangisi doğrudur?', 'İkisi de iki ayrı sözcük olarak yazılır.', ['İkisi de tek sözcük olarak bitişik yazılır: \'birdaha\', \'birde\'.', '\'Bir daha\' ayrı, \'bir de\' bitişik yazılır.', '\'Bir de\' ayrı, \'bir daha\' kısa çizgiyle yazılır.'], 'Bu ifadelerde \'bir\' sayı sıfatı, \'daha\' ve \'de\' ise ayrı sözcüklerdir.'),
  ('\'Kendi kendine konuşan çocuk\' ve \'yarı yarıya indirim\' ifadelerindeki tekrarlı öbekler için hangisi doğrudur?', 'İkisi de ayrı yazılır.', ['İkisi de kısa çizgiyle yazılır: \'kendi-kendine\', \'yarı-yarıya\'.', 'İkisi de bitişik yazılır: \'kendikendine\', \'yarıyarıya\'.', 'Yalnız \'kendi kendine\' bitişik yazılır.'], 'Aynı sözcüğün tekrarıyla kurulan bu öbekler ayrı yazılır.'),
  ('Aşağıdaki bağlaç ve bağlaç öbeklerinden hangisi ayrı yazılan iki sözcükten oluşur?', 'sonuç olarak', ['dolayısıyla', 'yoksa', 'hatta'], '\'Sonuç olarak\' iki sözcüktür; diğerleri tek sözcük olarak bitişik yazılır.'),
  ('\'Öte yandan\' ve \'bu bakımdan\' bağlaç öbeklerinin yazımı için hangisi doğrudur?', 'İkisi de ayrı yazılır.', ['İkisi de bitişik yazılır.', 'Yalnız \'öte yandan\' bitişik yazılır.', 'Yalnız \'bu bakımdan\' bitişik yazılır.'], 'Bunlar edat/zarf grubu olup sözcükleri ayrı yazılır.'),
  ('\'Bununla birlikte\' ve \'bu arada\' ifadeleri için hangisi doğrudur?', 'Sözcükleri ayrı yazılır.', ['Sözcükleri bitişik yazılır.', 'Yalnız \'bununla birlikte\' bitişik yazılır.', 'Yalnız \'bu arada\' bitişik yazılır.'], 'Bu ifadeler iki ya da daha fazla sözcükten oluşur ve ayrı yazılır.'),
  ('Murat, \'Her gün ayrı, hergün bitişik yazılabilir; ikisi de doğrudur.\' diyor. Bu görüş için hangisi doğrudur?', 'Yanlıştır; yalnız \'her gün\' ayrı yazımı doğrudur.', ['Doğrudur; ikisi de TDK\'ye uygundur.', 'Yanlıştır; yalnız \'hergün\' doğrudur.', 'Doğrudur; ikisi de ancak noktalı yazımda kullanılır.'], 'TDK\'ye göre \'her gün\' iki sözcük olarak yazılır.'),
  ('Günlük yaşamda bir şeye duyulan gereksinimi anlatan sözcüğün TDK\'ye uygun yazımı hangisidir?', 'ihtiyaç', ['ihtiyac', 'ihtyaç', 'ihtiyaşş'], 'Doğru yazım \'ihtiyaç\'tır; sonunda \'ç\' bulunur.'),
  ('Bir işle uğraştığı için başka işe vakit ayıramayan kişiyi anlatan sözcüğün doğru yazımı hangisidir?', 'meşgul', ['meşkul', 'meşgül', 'meşğuul'], 'Arapça kökenli sözcük \'meşgul\' biçiminde yazılır.'),
  ('Misafire yemek, içecek sunmak anlamındaki sözcüğün doğru yazımı hangisidir?', 'ikram', ['ikramm', 'ikrâm', 'ihram'], '\'İkram\' sözcüğü şapkasız ve tek \'m\' ile yazılır.'),
  ('Bir amaç ya da düşünceden dönmek anlamındaki sözcüğün TDK\'ye uygun yazımı hangisidir?', 'vazgeçmek', ['vaz geçmek', 'vazgecmek', 'vaz-geçmek'], '\'Vazgeç-\' fiili tek sözcük olarak bitişik yazılır.'),
  ('Bir cismi hareket ettirebilen etkiyi anlatan fizik terimi \'güç\' anlamındaki Arapça kökenli sözcüğün doğru yazımı hangisidir?', 'kuvvet', ['kuvet', 'kuvvat', 'kuvvett'], '\'Kuvvet\' sözcüğünde \'v\' ikizleşir.'),
  ('\'Dünkü maçta kaleci hergün antrenman yaptığını söyledi ve hakeme itiraz etmedi.\' cümlesinde kaç yazım yanlışı vardır?', 'bir', ['iki', 'üç', 'dört'], 'Yalnız \'her gün\' ayrı yazılmalıdır; \'dünkü\' doğrudur.'),
  ('\'Hava çok soğuktu yinede dışarı çıktık ve birşey almadan geri döndük.\' cümlesinde kaç yazım yanlışı vardır?', 'iki', ['bir', 'üç', 'dört'], '\'Yine de\' ve \'bir şey\' ayrı yazılmalıdır.'),
  ('Hangi cümlede \'hiçbir\' ve \'her şey\' doğru yazılmıştır?', 'Eskiden hiçbir şeyden korkmayan Kerem, şimdi her şeyden çekiniyor.', ['Eskiden hiç bir şeyden korkmayan Kerem, şimdi her şeyden çekiniyor.', 'Eskiden hiçbir şeyden korkmayan Kerem, şimdi herşeyden çekiniyor.', 'Eskiden hiçbirşeyden korkmayan Kerem, şimdi her şeyden çekiniyor.'], '\'Hiçbir\' bitişik, \'şey\' ve \'her şey\' ayrı yazılır.'),
  ('Aşağıdaki bileşik fiillerden hangisi ayrı yazılır?', 'teslim etmek', ['fethetmek', 'affetmek', 'kaybetmek'], '\'Teslim etmek\'te ses olayı yoktur; diğerleri ünlü düşmesi ya da ikizleşme nedeniyle bitişik yazılır.'),
  ('Aşağıdaki fiillerden hangisinin ayrı yazılması doğrudur?', 'hareket etmek', ['hükmetmek', 'sabretmek', 'zannetmek'], '\'Hareket etmek\' ses olayı olmayan bileşik fiildir; ayrı yazılır.'),
  ('\'Yok\' ve \'etmek\' sözcüklerinden oluşan fiilin doğru yazımı hangisidir?', 'yok etmek', ['yoketmek', 'yok-etmek', 'yokeetmek'], 'Bu bileşikte ses olayı bulunmaz; iki sözcük ayrı yazılır.'),
  ('\'Çocuk, bahçeye çıkıp oynadı.\' cümlesinde özne ile yüklem arasındaki virgül için hangisi doğrudur?', 'Gereksizdir; özneden sonra virgül konmaz.', ['Zorunludur; her fiilimsiden önce virgül konur.', 'Gereklidir; özne her zaman virgülle ayrılır.', 'Gereklidir; çünkü cümle uzundur.'], 'Özne ile yüklem arasına, anlam gerektirmedikçe virgül konmaz.'),
  ('\'Kitaplığa üç roman, iki sözlük ve bir atlas koydu.\' cümlesinde kaç virgül kullanılmıştır ve neden?', 'Bir virgül; \'ve\'den önceki iki öğeyi ayırır.', ['İki virgül; her öğeden sonra virgül konur.', 'Hiç virgül kullanılmamıştır.', 'Üç virgül; her sayıdan sonra virgül konur.'], 'Son öğeden önce \'ve\' olduğundan öğeler arasında yalnız bir virgül bulunur.'),
  ('\'Ey Türk gençliği! Birinci vazifen...\' sözünde üç noktanın görevi nedir?', 'Cümlenin devam ettiğini, alıntıda sözün sürdüğünü göstermek', ['Cümlenin soru olduğunu belirtmek', 'Sayı aralığı göstermek', 'Kısaltma yapmak'], 'Üç nokta, alıntıda sözün sürdüğünü ya da kesildiğini gösterebilir.'),
